// Tratamento Interativo de Comandos do Bot Telegram (@m360_IA_reporte_bot)
var p = msg.payload || {};
var chatId = p.chatId || (p.chat && p.chat.id) || (p.from && p.from.id);
var text = (p.content || p.text || "").trim();
var firstName = (p.from && p.from.first_name) || (p.chat && p.chat.first_name) || "Usuário";

if (!chatId) return null;

// Gestão de múltiplos inscritos no contexto global
var subscribers = global.get("telegram_subscribers") || [];
if (!Array.isArray(subscribers)) subscribers = [subscribers];

function addSubscriber(id, name, origin) {
    var exists = subscribers.find(function(s) { return String(s.chatId) === String(id); });
    if (!exists) {
        subscribers.push({
            chatId: id,
            name: name,
            origin: origin,
            registeredAt: new Date().toISOString()
        });
        global.set("telegram_subscribers", subscribers);
        global.set("TELEGRAM_CHAT_ID", String(id)); // Mantém como chat principal
    }
}

var replyText = "";
var lower = text.toLowerCase();
var agora = new Date().toLocaleTimeString("pt-BR", {hour: "2-digit", minute: "2-digit"});

// 1. /start convite
if (lower === "/start convite" || lower.startsWith("/start convite")) {
    flow.set("telegram_chatid_convite", chatId);
    addSubscriber(chatId, firstName, "convite");

    replyText = "🌱 *Olá, " + firstName + "! Seu acesso foi identificado como CONVITE.*\n\n" +
                "✅ Seu chatId (`" + chatId + "`) foi registrado com sucesso na Estufa M360!\n\n" +
                "Você passará a receber:\n" +
                "• 💧 Alertas automáticos de início e fim de irrigação\n" +
                "• ⚠️ Notificações de falha de conexão de nós da estufa\n" +
                "• 📊 Relatórios diários de telemetria\n\n" +
                "Digite */status* para ver a horta agora ou */ajuda* para ver os comandos disponíveis.";
}
// 2. /start padrão
else if (lower === "/start" || lower.startsWith("/start")) {
    addSubscriber(chatId, firstName, "manual");
    replyText = "🌱 *Olá, " + firstName + "! Bem-vindo ao M360 Horta Bot.*\n\n" +
                "🤖 *Status:* Bot ativo e conectado à rede da estufa.\n" +
                "🆔 *Seu Chat ID:* `" + chatId + "`\n\n" +
                "💡 *Comandos disponíveis:*\n" +
                "• */status* — Exibe a leitura em tempo real dos sensores e atuadores\n" +
                "• */id* — Exibe o seu Chat ID do Telegram\n" +
                "• */ajuda* — Instruções do sistema\n\n" +
                "_Se você veio por convite de administrador, use o link com ?start=convite._";
}
// 3. /id
else if (lower === "/id") {
    replyText = "🆔 *Identificação do Chat:*\n\n" +
                "• *Nome:* " + firstName + "\n" +
                "• *Chat ID:* `" + chatId + "`\n" +
                "• *Tipo de Chat:* " + ((p.chat && p.chat.type) || "Privado");
}
// 4. /status
else if (lower === "/status") {
    var nodes; try { nodes = global.get("mys_nodes", "file") || {}; } catch(e) { nodes = global.get("mys_nodes") || {}; }
    var n99 = nodes["99"] || {};
    var vals99 = n99.values || {};
    var n1 = nodes["1"] || {};
    var n2 = nodes["2"] || {};

    var temp = vals99["11"] || vals99["18"] || "N/A";
    var hum = vals99["12"] || vals99["19"] || "N/A";
    var flowRate = vals99["21"] || "0";
    var bat99 = n99.batteryVoltage ? n99.batteryVoltage + "V" : "N/A";

    replyText = "📊 *STATUS ATUAL DA HORTA M360* (" + agora + ")\n\n" +
                "🌡️ *Clima da Estufa (Nó 99):*\n" +
                "• Temperatura: *" + temp + " °C*\n" +
                "• Umidade do Ar: *" + hum + " %*\n" +
                "• Vazão Irrigação: *" + flowRate + " L/min*\n" +
                "• Alimentação: *" + bat99 + "*\n\n" +
                "🌱 *Rede de Sensores:*\n" +
                "• *Nó 01 (Solo A):* " + (n1.status || "Ativo") + "\n" +
                "• *Nó 02 (Solo B):* " + (n2.status || "Ativo") + "\n" +
                "• *Nó 99 (Atuadores):* " + (n99.status || "Ativo") + "\n\n" +
                "⚙️ _Automação de irrigação operando em modo automático no Canteiro B._";
}
// 5. /tempo ou /previsao
else if (lower === "/tempo" || lower === "/previsao" || lower.startsWith("/tempo") || lower.startsWith("/previsao")) {
    var pMeteo = flow.get("previsao_tempo") || flow.get("agro_meteo") || {};
    if (pMeteo.tempExt !== undefined) {
        replyText = "🌤️ *PREVISÃO DO TEMPO & CLIMA ATUAL*\n\n" +
                    "📍 *Estufa M360* (Atualizado às " + (pMeteo.updatedAtStr || agora) + ")\n\n" +
                    "🌡️ *Temperatura Externa:* *" + pMeteo.tempExt + " °C* (Orvalho: " + pMeteo.pontoOrvalho + " °C)\n" +
                    "💧 *Umidade Externa:* *" + pMeteo.humExt + " %*\n" +
                    "💨 *VPD:* *" + pMeteo.vpdAtual + " kPa*\n" +
                    "☀️ *Radiação Solar:* *" + pMeteo.radAtual + " W/m²*\n" +
                    "🌾 *Evapotranspiração (ET₀):* *" + pMeteo.et0Atual + " mm/h*\n" +
                    "🌧️ *Chuva próx. 4h:* *" + pMeteo.probChuvaMax + "% (" + pMeteo.precipTotal4h + " mm)*\n" +
                    "🌬️ *Vento:* *" + pMeteo.ventoAtual + " km/h*\n\n" +
                    "⚙️ _Boletins automáticos programados para 06:00, 11:00, 16:00 e 21:00._";
    } else {
        replyText = "🌤️ *Previsão do Tempo:* Carregando dados da estação agroclimática...";
    }
}
// 6. /ajuda
else if (lower === "/ajuda" || lower === "ajuda") {
    replyText = "ℹ️ *M360 Horta — Ajuda e Comandos:*\n\n" +
                "• */status* — Consulta o clima interno da estufa e atuadores em tempo real\n" +
                "• */tempo* — Exibe a previsão do tempo externa e índices agroclimáticos\n" +
                "• */id* — Mostra seu Chat ID\n" +
                "• */start convite* — Registra-se para receber alertas e boletins diários\n" +
                "• */ajuda* — Exibe este menu de ajuda";
}
else {
    replyText = "🤖 Comando não reconhecido. Digite */status*, */tempo* ou */ajuda* para mais opções.";
}

msg.payload = {
    chatId: chatId,
    type: "message",
    content: replyText,
    options: {
        parse_mode: "Markdown"
    }
};

return msg;

var data = msg.payload;
if (!data || !data.hourly || !data.hourly.time) {
    node.error("Resposta inválida da API Open-Meteo", msg);
    return null;
}

var times = data.hourly.time;
var probs = data.hourly.precipitation_probability || [];
var precips = data.hourly.precipitation || [];
var temps = data.hourly.temperature_2m || [];
var hums = data.hourly.relative_humidity_2m || [];
var dews = data.hourly.dew_point_2m || [];
var et0s = data.hourly.et0_fao_evapotranspiration || [];
var vpds = data.hourly.vapour_pressure_deficit || [];
var rads = data.hourly.shortwave_radiation_instant || [];
var winds = data.hourly.wind_speed_10m || [];

var now = new Date();
var currentHour = now.getHours();
var currentHourTs = now.getTime();

// 1. Encontrar índice da hora corrente
var idxAtual = 0;
var menorDiff = Infinity;
for (var i = 0; i < times.length; i++) {
    var t = new Date(times[i]).getTime();
    var diff = Math.abs(t - currentHourTs);
    if (diff < menorDiff) {
        menorDiff = diff;
        idxAtual = i;
    }
}

// 2. Variáveis instantâneas da hora corrente
var tempAtual = temps[idxAtual] || 0;
var humAtual = hums[idxAtual] || 0;
var dewAtual = dews[idxAtual] || 0;
var vpdAtual = vpds[idxAtual] || 0;
var et0Atual = et0s[idxAtual] || 0;
var radAtual = rads[idxAtual] || 0;
var ventoAtual = winds[idxAtual] || 0;

// 3. Janela de previsão das próximas 6 horas
var JANELA = 6;
var probChuvaMax = 0;
var precipTotal = 0;
for (var j = idxAtual; j < idxAtual + JANELA && j < times.length; j++) {
    var p = probs[j] || 0;
    var prec = precips[j] || 0;
    if (p > probChuvaMax) probChuvaMax = p;
    precipTotal += prec;
}

// Salva no contexto de fluxo para consulta via comando /tempo
flow.set("previsao_tempo", {
    tempExt: parseFloat(tempAtual.toFixed(1)),
    humExt: parseFloat(humAtual.toFixed(0)),
    pontoOrvalho: parseFloat(dewAtual.toFixed(1)),
    vpdAtual: parseFloat(vpdAtual.toFixed(2)),
    et0Atual: parseFloat(et0Atual.toFixed(2)),
    radAtual: parseFloat(radAtual.toFixed(0)),
    ventoAtual: parseFloat(ventoAtual.toFixed(1)),
    probChuvaMax: probChuvaMax,
    precipTotal4h: parseFloat(precipTotal.toFixed(1)),
    updatedAtStr: now.toLocaleTimeString("pt-BR", {hour: "2-digit", minute: "2-digit"})
});

// 4. Cabeçalho de acordo com o horário agendado (06h, 11h, 16h, 21h)
var saudacao = "";
if (currentHour < 9) {
    saudacao = "🌅 *PREVISÃO DO TEMPO: ABERTURA DO DIA (06:00)*";
} else if (currentHour < 14) {
    saudacao = "☀️ *PREVISÃO DO TEMPO: MEIO-DIA & PICO SOLAR (11:00)*";
} else if (currentHour < 19) {
    saudacao = "⛅ *PREVISÃO DO TEMPO: TARDE & FIM DO CICLO DIURNO (16:00)*";
} else {
    saudacao = "🌙 *PREVISÃO DO TEMPO: NOITE & CLIMA NOTURNO (21:00)*";
}

var agoraStr = now.toLocaleTimeString("pt-BR", {hour: "2-digit", minute: "2-digit"});
var dataStr = now.toLocaleDateString("pt-BR");

// 5. Recomendação agronômica inteligente para o manejo da estufa
var recManejo = "";
if (probChuvaMax >= 60 && precipTotal >= 2.0) {
    recManejo = "🌧️ *Chuva Prevista:* Risco de saturação em canteiros abertos. Redução automática de rega recomendada.";
} else if (vpdAtual > 1.8) {
    recManejo = "⚠️ *Ar Muito Seco (VPD alto):* Risco de estresse hídrico. Atenção à taxa de transpiração das mudas.";
} else if (vpdAtual < 0.4 && humAtual > 85) {
    recManejo = "💧 *Umidade Elevada (VPD baixo):* Transpiração lenta. Recomendada ventilação para evitar fungos.";
} else {
    recManejo = "✅ *Condições Ideais:* Faixa climática favorável para fotossíntese e desenvolvimento vegetativo.";
}

var chuvaInfo = (probChuvaMax > 0) ? (probChuvaMax + "% (est. " + precipTotal.toFixed(1) + " mm)") : "0% (Sem chuva prevista)";

var texto = saudacao + "\n\n" +
    "📍 *Localização:* Estufa M360 (-15.96°, -47.80°)\n" +
    "🕒 *Horário:* " + dataStr + " às " + agoraStr + "\n\n" +
    "🌡️ *Temperatura:* *" + tempAtual.toFixed(1) + " °C* (Orvalho: " + dewAtual.toFixed(1) + " °C)\n" +
    "💧 *Umidade do Ar:* *" + humAtual.toFixed(0) + " %*\n" +
    "💨 *VPD (Déficit de Pressão):* *" + vpdAtual.toFixed(2) + " kPa*\n" +
    "☀️ *Radiação Solar:* *" + radAtual.toFixed(0) + " W/m²*\n" +
    "🌾 *Evapotranspiração (ET₀):* *" + et0Atual.toFixed(2) + " mm/h*\n" +
    "🌬️ *Vento:* *" + ventoAtual.toFixed(1) + " km/h*\n" +
    "🌧️ *Chuva próx. 6h:* *" + chuvaInfo + "*\n\n" +
    "💡 *Recomendação Agronômica:*\n" + recManejo;

// 6. Enviar para todos os chats registrados
var subscribers = global.get("telegram_subscribers") || [];
if (!Array.isArray(subscribers)) subscribers = [subscribers];

var chatIds = [];
var mainChat = env.get("TELEGRAM_CHAT_ID") || global.get("TELEGRAM_CHAT_ID") || "";
chatIds.push(String(mainChat));

subscribers.forEach(function(s) {
    var id = s && (s.chatId || s);
    if (id && chatIds.indexOf(String(id)) === -1) {
        chatIds.push(String(id));
    }
});

var msgs = [];
chatIds.forEach(function(cId) {
    msgs.push({
        payload: {
            chatId: cId,
            type: "message",
            content: texto,
            options: {
                parse_mode: "Markdown"
            }
        }
    });
});

node.status({fill: "green", shape: "dot", text: "Boletim enviado às " + agoraStr + " (" + chatIds.length + " chats)"});
return [msgs];

var prefix = global.get('mqtt_topic_prefix') || 'm360/DF/0000';
var m = msg.payload;
if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch(e) {}
}
if (m && typeof m === 'object' && m.nodeId !== undefined) {
    var nodeId   = m.nodeId;
    var sensorId = m.sensorId !== undefined ? m.sensorId : 0;
    var command  = m.command !== undefined ? m.command : 1;
    var ack      = m.ack !== undefined ? m.ack : 0;
    var type     = m.type !== undefined ? m.type : 2;
    var payload  = m.payload !== undefined ? String(m.payload) : '';
    msg.topic = prefix + '/in/' + nodeId + '/' + sensorId + '/' + command + '/' + ack + '/' + type;
    msg.payload = payload;
} else {
    msg.topic = prefix + '/in';
}
return msg;

// Salva o estado dos seletores no contexto do fluxo
if (msg.topic === "selectedNodeId") {
    flow.set("ui_selected_node_id", msg.payload);
    return null;
}
if (msg.topic === "selectedAction") {
    flow.set("ui_selected_action", msg.payload);
    return null;
}
if (msg.topic === "selectedInterval") {
    var val = parseInt(msg.payload, 10);
    if (!isNaN(val) && val >= 1 && val <= 1440) {
        flow.set("ui_selected_interval", val);
    }
    return null;
}

// Ao receber o trigger do botão
if (msg.topic === "trigger") {
    var nodeId = flow.get("ui_selected_node_id") || 1;
    var action = flow.get("ui_selected_action") || "REPRESENT";

    var payloadObj = {};
    if (action === "REPRESENT") {
        payloadObj = {
            nodeId: Number(nodeId),
            sensorId: 0,
            command: 1,
            type: 48,
            payload: "REPRESENT"
        };
    } else if (action === "FORCE_UPDATE") {
        payloadObj = {
            nodeId: Number(nodeId),
            sensorId: 0,
            command: 1,
            type: 48,
            payload: "FORCE_UPDATE"
        };
    } else if (action === "DEBUG") {
        payloadObj = {
            nodeId: Number(nodeId),
            sensorId: 0,
            command: 1,
            type: 48,
            payload: "DEBUG_NET"
        };
    } else if (action === "SET_INTERVAL") {
        var intervalMin = flow.get("ui_selected_interval") || 5;
        payloadObj = {
            nodeId: Number(nodeId),
            sensorId: 254, // M360_CHILD_ID_INTERVAL
            command: 1,    // C_SET
            type: 24,      // V_VAR1
            payload: Number(intervalMin)
        };
    }

    msg.payload = payloadObj;
    return msg;
}
return null;

// Opcoes do dropdown a partir dos nos descobertos (mys_nodes).
// Dedupe: so envia quando o CONJUNTO de nos muda, evitando flood a cada mensagem
// MySensors que faria o ui-dropdown engasgar. Nunca envia lista vazia (nao apaga o widget).
var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var options = [];
Object.keys(nodes).sort(function(a,b) { return Number(a) - Number(b); }).forEach(function(id) {
    var n = nodes[id];
    var nome = n.sketchName || n.presentName || '';
    options.push({ label: 'No ' + id + (nome ? ' (' + nome + ')' : ''), value: Number(id) });
});
var sig = options.map(function(o) { return o.value + ':' + o.label; }).join('|');
if (options.length === 0) { return null; }
if (sig === flow.get('dropdown_sig')) { return null; }
flow.set('dropdown_sig', sig);
return { options: options };

// Despachante & Feedback Imediato Solenóides
var p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch(e) {}
}

var buttonIndexMap = {
    '31:1': 0, // Ligar Solenóide A
    '31:0': 1, // Desligar Solenóide A
    '32:1': 2, // Ligar Solenóide B
    '32:0': 3, // Desligar Solenóide B
    '33:1': 4, // Ligar Solenóide C
    '33:0': 5, // Desligar Solenóide C
    'admin': 6  // Botão Enviar Comando
};

var buttonIdMap = {
    '31:1': 'd24ac9884d836b5f',
    '31:0': '5a74fe774d0b8e06',
    '32:1': 'd5113aa8b58b627f',
    '32:0': 'f322977c0cdba1a5',
    '33:1': '06bc82b2a8afaa23',
    '33:0': 'fe082f23b6ace22b',
    'admin': '2c4b494c55bff84b'
};

var key = (p && p.sensorId !== undefined && p.payload !== undefined && p.type === 2) 
          ? (p.sensorId + ':' + p.payload) 
          : 'admin';

var idx = buttonIndexMap[key] !== undefined ? buttonIndexMap[key] : 6;
var bId = buttonIdMap[key] || '2c4b494c55bff84b';

if (p && typeof p === 'object') {
    p._buttonId = bId;
    msg.payload = p;
}

// Mensagem de Feedback Imediato (Amarelo / Pendente)
var pendingMsg = {
    ui_update: {
        buttonColor: '#f59e0b',
        textColor: '#ffffff'
    },
    buttonColor: '#f59e0b',
    textColor: '#ffffff'
};

var outputs = [null, null, null, null, null, null, null, null];
outputs[idx] = pendingMsg;
outputs[7] = msg; // Comando enviado ao Sincronizador ACK

return outputs;

// Processador de Feedback & Estado Visual Solenóides (Dashboard 2.0)
var status = msg.status;
var buttonId = msg.buttonId;
var sensorId = msg.sensorId;
var val = String(msg.value !== undefined ? msg.value : '');

var COLOR_DEFAULT = "#0284c7"; // Azul Primário
var COLOR_ACTIVE  = "#10b981"; // Verde Ativo
var COLOR_ERROR   = "#ef4444"; // Vermelho
var COLOR_PENDING = "#f59e0b"; // Âmbar
var COLOR_MAILBOX = "#6366f1"; // Índigo — retido na Caixa Postal (nó LP dormindo)

var solState = flow.get('solenoid_states') || { 31: false, 32: false, 33: false };

var outputs = [null, null, null, null, null, null, null];

function makeStyle(color) {
    var c = color || COLOR_DEFAULT;
    return {
        ui_update: { buttonColor: c, textColor: '#ffffff' },
        buttonColor: c,
        textColor: '#ffffff'
    };
}

// Caixa Postal (nós LP): 'enqueued' fica índigo enquanto retido; 'dispatched'
// pisca verde e volta ao estado real. Sem isso o botão ficava âmbar para sempre,
// porque o despacho da Mailbox não entra na fila de ACK (o nó LP dorme antes
// de qualquer retry, então rastrear ACK ali só geraria falha falsa).
var mailboxIndexMap = {
    'd24ac9884d836b5f': 0, '5a74fe774d0b8e06': 1,
    'd5113aa8b58b627f': 2, 'f322977c0cdba1a5': 3,
    '06bc82b2a8afaa23': 4, 'fe082f23b6ace22b': 5,
    '2c4b494c55bff84b': 6
};
if (status === 'mailbox_enqueued' || status === 'mailbox_dispatched') {
    var mIdx = buttonId !== undefined && buttonId !== null ? mailboxIndexMap[buttonId] : undefined;
    if (mIdx === undefined) return null;
    if (status === 'mailbox_enqueued') {
        outputs[mIdx] = makeStyle(COLOR_MAILBOX);
        return outputs;
    }
    outputs[mIdx] = makeStyle(COLOR_ACTIVE);
    setTimeout(function () {
        var st = flow.get('solenoid_states') || { 31: false, 32: false, 33: false };
        var r = [null, null, null, null, null, null, null];
        var onIdx = { 0: 31, 2: 32, 4: 33 }[mIdx];
        r[mIdx] = makeStyle(onIdx && st[onIdx] ? COLOR_ACTIVE : COLOR_DEFAULT);
        node.send(r);
    }, 1500);
    return outputs;
}

if (status === 'error') {
    var errorIndexMap = {
        'd24ac9884d836b5f': 0, '5a74fe774d0b8e06': 1,
        'd5113aa8b58b627f': 2, 'f322977c0cdba1a5': 3,
        '06bc82b2a8afaa23': 4, 'fe082f23b6ace22b': 5,
        '2c4b494c55bff84b': 6
    };
    var idx = buttonId ? errorIndexMap[buttonId] : -1;
    if (idx !== -1) {
        outputs[idx] = makeStyle(COLOR_ERROR);
        setTimeout(function() {
            var currentSolState = flow.get('solenoid_states') || { 31: false, 32: false, 33: false };
            var resetOutputs = [null, null, null, null, null, null, null];
            resetOutputs[0] = makeStyle(currentSolState[31] ? COLOR_ACTIVE : COLOR_DEFAULT);
            resetOutputs[1] = makeStyle(COLOR_DEFAULT);
            resetOutputs[2] = makeStyle(currentSolState[32] ? COLOR_ACTIVE : COLOR_DEFAULT);
            resetOutputs[3] = makeStyle(COLOR_DEFAULT);
            resetOutputs[4] = makeStyle(currentSolState[33] ? COLOR_ACTIVE : COLOR_DEFAULT);
            resetOutputs[5] = makeStyle(COLOR_DEFAULT);
            resetOutputs[6] = makeStyle(COLOR_DEFAULT);
            node.send(resetOutputs);
        }, 2000);
        return outputs;
    }
}

if (status === 'success' || (msg.payload && msg.payload.sensorId && msg.payload.command === 1 && msg.payload.type === 2)) {
    var sid = sensorId || (msg.payload ? msg.payload.sensorId : null);
    var v = (val !== '' && val !== undefined) ? val : (msg.payload ? String(msg.payload.payload) : '0');

    if (sid == 31 || sid == 32 || sid == 33) {
        var isOn = (v === '1' || v === 'true');

        if (isOn) {
            solState[31] = (sid == 31);
            solState[32] = (sid == 32);
            solState[33] = (sid == 33);
        } else {
            solState[sid] = false;
        }
        flow.set('solenoid_states', solState);

        // Atualiza botões "Ligar": Verde se ativo, Azul se desligado
        outputs[0] = makeStyle(solState[31] ? COLOR_ACTIVE : COLOR_DEFAULT);
        outputs[2] = makeStyle(solState[32] ? COLOR_ACTIVE : COLOR_DEFAULT);
        outputs[4] = makeStyle(solState[33] ? COLOR_ACTIVE : COLOR_DEFAULT);

        // Botão Desligar: Verde rápido de confirmação (1.2s) e volta para Azul
        var offIdx = (sid == 31 ? 1 : (sid == 32 ? 3 : 5));
        if (!isOn) {
            outputs[offIdx] = makeStyle(COLOR_ACTIVE);
            setTimeout(function() {
