    } else if (buttonId === '2c4b494c55bff84b') {
        outputs[6] = makeStyle(COLOR_ACTIVE);
        setTimeout(function() {
            var r = [null, null, null, null, null, null, null];
            r[6] = makeStyle(COLOR_DEFAULT);
            node.send(r);
        }, 1500);
        return outputs;
    }
}

return null;

var prefix = global.get('mqtt_topic_prefix') || 'm360/DF/0000';
var m = msg.payload;
if (typeof m === 'string') {
