    var payload  = m.payload !== undefined ? String(m.payload) : '';
    msg.topic = prefix + '/in/' + nodeId + '/' + sensorId + '/' + command + '/' + ack + '/' + type;
    msg.payload = payload;
} else {
    msg.topic = prefix + '/in';
}
return msg;

// Despachante & Feedback Imediato Bombas
var p = msg.payload;
if (typeof p === 'string') {
    try { p = JSON.parse(p); } catch(e) {}
}

var buttonIndexMap = {
    '38:1': 0, // Ligar Bomba NFT
    '38:0': 1, // Desligar Bomba NFT
    '39:1': 2, // Ligar Bomba Oxi
    '39:0': 3  // Desligar Bomba Oxi
};

var buttonIdMap = {
    '38:1': 'ad676d3d3b01fdfb',
    '38:0': 'e159c6a41b612278',
    '39:1': '816fdc9c18b87b2f',
    '39:0': '1b2ef9f3f78dd3e4'
};

var key = (p && p.sensorId !== undefined && p.payload !== undefined) ? (p.sensorId + ':' + p.payload) : '';
var idx = buttonIndexMap[key] !== undefined ? buttonIndexMap[key] : -1;
var bId = buttonIdMap[key] || '';

if (idx === -1) return null;

