// Processador de Feedback & Estado Visual Bombas (Dashboard 2.0)
var status = msg.status;
var buttonId = msg.buttonId;
var sensorId = msg.sensorId;
var val = String(msg.value !== undefined ? msg.value : '');

var COLOR_DEFAULT = "#0284c7"; // Azul Primário
var COLOR_ACTIVE  = "#10b981"; // Verde Ativo
var COLOR_ERROR   = "#ef4444"; // Vermelho

var pumpState = flow.get('pump_states') || { 38: false, 39: false };

var outputs = [null, null, null, null];

function makeStyle(color) {
    var c = color || COLOR_DEFAULT;
    return {
        ui_update: { buttonColor: c, textColor: '#ffffff' },
        buttonColor: c,
        textColor: '#ffffff'
    };
}

if (status === 'error') {
    var errorIndexMap = {
        'ad676d3d3b01fdfb': 0, 'e159c6a41b612278': 1,
        '816fdc9c18b87b2f': 2, '1b2ef9f3f78dd3e4': 3
    };
    var idx = buttonId ? errorIndexMap[buttonId] : -1;
    if (idx !== -1) {
        outputs[idx] = makeStyle(COLOR_ERROR);
        setTimeout(function() {
            var currentPumpState = flow.get('pump_states') || { 38: false, 39: false };
            var resetOutputs = [null, null, null, null];
            resetOutputs[0] = makeStyle(currentPumpState[38] ? COLOR_ACTIVE : COLOR_DEFAULT);
            resetOutputs[1] = makeStyle(COLOR_DEFAULT);
            resetOutputs[2] = makeStyle(currentPumpState[39] ? COLOR_ACTIVE : COLOR_DEFAULT);
            resetOutputs[3] = makeStyle(COLOR_DEFAULT);
            node.send(resetOutputs);
        }, 2000);
        return outputs;
    }
}

if (status === 'success' || (msg.payload && msg.payload.sensorId && msg.payload.command === 1 && msg.payload.type === 2)) {
    var sid = sensorId || (msg.payload ? msg.payload.sensorId : null);
    var v = (val !== '' && val !== undefined) ? val : (msg.payload ? String(msg.payload.payload) : '0');

    if (sid == 38 || sid == 39) {
        var isOn = (v === '1' || v === 'true');
        pumpState[sid] = isOn;
        flow.set('pump_states', pumpState);

        outputs[0] = makeStyle(pumpState[38] ? COLOR_ACTIVE : COLOR_DEFAULT);
        outputs[2] = makeStyle(pumpState[39] ? COLOR_ACTIVE : COLOR_DEFAULT);

        var offIdx = (sid == 38 ? 1 : 3);
        if (!isOn) {
            outputs[offIdx] = makeStyle(COLOR_ACTIVE);
            setTimeout(function() {
                var r = [null, null, null, null];
                r[offIdx] = makeStyle(COLOR_DEFAULT);
                node.send(r);
            }, 1200);
        } else {
            outputs[offIdx] = makeStyle(COLOR_DEFAULT);
        }

        return outputs;
    }
}

return null;

var prefix = global.get('mqtt_topic_prefix');
if (!prefix) {
    prefix = 'm360/DF/0000';
    global.set('mqtt_topic_prefix', prefix);
}
if (flow.get('ack_timeout_ms') === null || flow.get('ack_timeout_ms') === undefined) {
    flow.set('ack_timeout_ms', 5000);
}
if (flow.get('ack_max_retries') === null || flow.get('ack_max_retries') === undefined) {
    flow.set('ack_max_retries', 3);
}
if (flow.get('nodes_ttl_ms') === null || flow.get('nodes_ttl_ms') === undefined) {
    flow.set('nodes_ttl_ms', 172800000);
}

// Carregar credenciais do Telegram a partir de variáveis de ambiente do Node-RED
var tgToken = env.get("TELEGRAM_BOT_TOKEN") || global.get("TELEGRAM_BOT_TOKEN") || "";
var tgChatId = env.get("TELEGRAM_CHAT_ID") || global.get("TELEGRAM_CHAT_ID") || "";
if (tgToken) global.set("TELEGRAM_BOT_TOKEN", tgToken);
if (tgChatId) global.set("TELEGRAM_CHAT_ID", tgChatId);

if (!global.get('telegram_subscribers') && tgChatId) {
    global.set('telegram_subscribers', [{ chatId: tgChatId, name: 'Admin', origin: 'admin', registeredAt: new Date().toISOString() }]);
}

node.status({fill:'green',shape:'dot',text:'prefix='+prefix+' timeout='+flow.get('ack_timeout_ms')+'ms'});
msg.payload = {mqtt_topic_prefix:prefix, ack_timeout_ms:flow.get('ack_timeout_ms'), ack_max_retries:flow.get('ack_max_retries')};
return msg;

// Sincronizador de Comandos, Fila ACK e Caixa Postal (Mailbox) para Nós Low Power (LP)
var MQTT_PREFIX = global.get('mqtt_topic_prefix') || 'm360/DF/0000';
var TIMEOUT_MS  = flow.get('ack_timeout_ms')  || 5000;
var MAX_RETRIES = flow.get('ack_max_retries') || 3;

// Controle manual de ativacao/desativacao do sincronismo
var enableSync = flow.get('ack_sync_enabled');
if (enableSync === null || enableSync === undefined) {
    enableSync = true;
    flow.set('ack_sync_enabled', true);
}

if (msg.payload === 'ENABLE_ACK_SYNC') {
    flow.set('ack_sync_enabled', true);
    node.status({ fill: 'green', shape: 'dot', text: 'Sincronismo: Ativo' });
    return null;
}
if (msg.payload === 'DISABLE_ACK_SYNC') {
    flow.set('ack_sync_enabled', false);
    var t = context.get('timer');
    if (t) { clearTimeout(t); context.set('timer', null); }
    context.set('waiting', false);
    context.set('queue', []);
    node.status({ fill: 'red', shape: 'ring', text: 'Sincronismo: Inativo (Bypass)' });
    return null;
}

// ─── Helpers ─────────────────────────────────────────────────────

function iniciarItem(item) {
    context.set('waiting', true);
    context.set('targetNode', item.targetNode);
    context.set('targetSensor', item.targetSensor);
    context.set('currentItem', item);
    context.set('retries', 0);
    agendarTimeout(item, 0);
    node.status({
        fill: 'yellow', shape: 'dot',
        text: 'Aguardando ACK nó ' + item.targetNode + ' sensor ' + item.targetSensor
    });
    node.send([item.mqttMsg, null]);
}

function agendarTimeout(item, tentativa) {
    var t = context.get('timer');
    if (t) { clearTimeout(t); context.set('timer', null); }

    var delay = TIMEOUT_MS * Math.pow(2, tentativa);
    var newTimer = setTimeout(function () {
        if (!context.get('waiting')) return;
        var retries = (context.get('retries') || 0) + 1;
        context.set('retries', retries);

        if (retries < MAX_RETRIES) {
            node.warn('Timeout ACK Nó ' + item.targetNode +
                ' sensor ' + item.targetSensor +
                ' — Tentativa ' + (retries + 1) + '/' + MAX_RETRIES);
            node.send([item.mqttMsg, null]);
            agendarTimeout(item, retries);
        } else {
            context.set('waiting', false);
            context.set('timer', null);
            context.set('retries', 0);
            node.error('Falha definitiva — Nó ' + item.targetNode +
                ' sensor ' + item.targetSensor +
                ' após ' + MAX_RETRIES + ' tentativas');
            node.status({
                fill: 'red', shape: 'ring',
                text: 'Falha nó ' + item.targetNode +
                    ' | fila: ' + (context.get('queue') || []).length
            });
            node.send([null, {
                payload: 'Erro: Timeout após ' + MAX_RETRIES + ' tentativas — Nó ' + item.targetNode,
                status: 'error',
                buttonId: item.buttonId,
                nodeId: item.targetNode,
                sensorId: item.targetSensor,
                value: item.payload,
                // A fila de ACK so recebe comando de rele (isRelayCmd), entao
                // command/type sao sempre 1/2 aqui. Carimbados para que o
                // 'Monitor de Falhas' distinga atuacao de comando administrativo.
                command: 1,
                type: 2
            }]);
            var queue = context.get('queue') || [];
            if (queue.length > 0) {
                var next = queue.shift();
                context.set('queue', queue);
                iniciarItem(next);
            }
        }
    }, delay);
    context.set('timer', newTimer);
}

// ─── 1. Mensagens de Telemetria / Despertar / ACK do Gateway ──────
// Só é telemetria o que passou pelo 'Decodificador Nativo MySensors': ele
// carimba `direction` ('sensor' ou 'transport_ack') e reescreve o tópico para
// {prefix}/out. NUNCA discriminar por nodeId+command: o comando novo vindo da
// UI também tem esses dois campos e caia aqui, morrendo no `return null` do
// fim do bloco. O Sincronizador nunca entrava em 'waiting', o eco do nó não
// era reconhecido como confirmação e o botão ficava preso em âmbar.
var inbound = msg.payload;
if (typeof inbound === 'string') {
    try { inbound = JSON.parse(inbound); } catch (e) { inbound = null; }
}
var isTelemetria = !!(inbound && typeof inbound === 'object' &&
                      inbound.direction !== undefined &&
                      inbound.nodeId !== undefined);

if (isTelemetria) {
    var data = inbound;

    var nId = Number(data.nodeId);

    // ─── 1.1 Verificação da Caixa Postal (Mailbox) para Nós LP ───
    var mailbox = global.get('m360_mailbox') || {};
    if (mailbox[nId]) {
        var queued = mailbox[nId];
        delete mailbox[nId];
        global.set('m360_mailbox', mailbox);

        node.warn('Nó ' + nId + ' acordou! Despachando comando retido da Mailbox.');

        var dispatchNotice = {
            payload: '🎯 Nó ' + nId + ' acordou! Despachando comando retido da Caixa Postal: ' + queued.desc,
            status: 'mailbox_dispatched',
            buttonId: queued.buttonId,
            nodeId: nId,
            sensorId: queued.sensorId,
            value: queued.value,
            desc: queued.desc
        };

        // Dispara o comando MQTT imediatamente enquanto o rádio do nó está acordado (janela smartSleep)
        node.send([queued.mqttMsg, dispatchNotice]);
    }

    // ─── 1.2 Tratamento de Confirmação ACK de Atuação ────────────
    if (enableSync && context.get('waiting')) {
        var targetNode = context.get('targetNode');
        var targetSensor = context.get('targetSensor');
        var currentItem = context.get('currentItem') || { targetNode: targetNode, targetSensor: targetSensor };

        var isConfirmation = (
            data.nodeId == targetNode &&
            (targetSensor == 255 || data.sensorId == targetSensor) &&
            data.command === 1 && data.type === 2 && data.ack === 0 &&
            String(data.payload) === String(currentItem.payload)
        );

        if (isConfirmation) {
            var t = context.get('timer');
            if (t) { clearTimeout(t); context.set('timer', null); }
            context.set('waiting', false);
            context.set('retries', 0);

            var queue = context.get('queue') || [];
            node.status({
                fill: 'green', shape: 'dot',
                text: 'OK nó ' + targetNode + ' sensor ' + targetSensor + ' | fila: ' + queue.length
            });

            var successMsg = {
                payload: 'Sucesso: Nó ' + targetNode + ' sensor ' + targetSensor + ' confirmou',
                status: 'success',
                buttonId: currentItem.buttonId,
                nodeId: targetNode,
                sensorId: targetSensor,
                value: currentItem.payload,
                command: 1,
                type: 2
            };

            if (queue.length > 0) {
                var next = queue.shift();
                context.set('queue', queue);
                iniciarItem(next);
            }

            return [null, successMsg];
        }
    }

    return null;
}

// ─── 2. Novo Comando Recebido (da UI ou Automação) ─────────────────
var requestData = msg.payload;
if (typeof requestData === 'string') {
    try { requestData = JSON.parse(requestData); } catch (e) {
        return [null, { payload: 'Erro: JSON malformado: ' + msg.payload, status: 'error' }];
    }
}

if (!requestData || requestData.nodeId === undefined || requestData.command === undefined) {
    return null;
}

var targetNode = (requestData && requestData.nodeId !== undefined) ? Number(requestData.nodeId) : 99;
var targetSensor = (requestData && requestData.sensorId !== undefined) ? Number(requestData.sensorId) : 255;
var buttonId = requestData._buttonId || requestData.buttonId || null;

var cmdToSend     = requestData.command  !== undefined ? requestData.command  : 1;
var typeToSend    = requestData.type     !== undefined ? requestData.type     : 2;
var payloadToSend = requestData.payload  !== undefined ? String(requestData.payload) : '';

var mqttMsg = {
    topic:   MQTT_PREFIX + '/in/' + targetNode + '/' + targetSensor + '/' + cmdToSend + '/0/' + typeToSend,
    payload: payloadToSend
};

// Identifica se o nó alvo e Low Power (LP / bateria)
var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var nInfo = nodes[targetNode];
var isLP = false;
if (nInfo) {
    if (nInfo.sketchName && nInfo.sketchName.indexOf('[LP]') !== -1) isLP = true;
    else if (targetNode === 4 || targetNode === 1 || targetNode === 2) isLP = true;
    else if (nInfo.cycleMs && nInfo.cycleMs > 15000) isLP = true;
} else if (targetNode === 4 || targetNode === 1 || targetNode === 2) {
    isLP = true;
}

var isAwakeRecently = (nInfo && (Date.now() - nInfo.lastSeen < 2000));

// Se o no for LP e nao acabou de transmitir, enfileira na Caixa Postal (Mailbox)
if (isLP && !isAwakeRecently) {
    var mailbox = global.get('m360_mailbox') || {};
    var descText = (targetSensor === 254 ? ('Ajustar Intervalo para ' + payloadToSend + ' min') : ('Comando Child ' + targetSensor + ' = ' + payloadToSend));

    mailbox[targetNode] = {
        mqttMsg: mqttMsg,
        targetNode: targetNode,
        sensorId: targetSensor,
        buttonId: buttonId,
        value: payloadToSend,
        desc: descText,
        enqueuedAt: Date.now()
    };
    global.set('m360_mailbox', mailbox);

    node.status({ fill: 'blue', shape: 'ring', text: 'Mailbox Nó ' + targetNode + ' (LP retido)' });

    var pendingNotice = {
        payload: '⏳ Comando retido na Caixa Postal: Nó ' + targetNode + ' está hibernando. Será entregue no próximo despertar.',
        status: 'mailbox_enqueued',
        buttonId: buttonId,
        nodeId: targetNode,
        sensorId: targetSensor,
        value: payloadToSend,
        desc: descText,
        command: cmdToSend,
        type: typeToSend
    };

    return [null, pendingNotice];
}

// Envio imediato para nós Always-On ou se o nó LP estiver acordado agora
var isRelayCmd = (requestData.command === 1 && requestData.type === 2);
if (!enableSync || targetNode === 255 || requestData.command === 3 || !isRelayCmd) {
    node.status(!enableSync
        ? { fill: 'red', shape: 'ring', text: 'Sincronismo: Inativo (Bypass)' }
        : { fill: 'blue', shape: 'dot', text: 'Enviado: nó ' + targetNode });
    return [mqttMsg, {
        payload: 'Enviado: nó ' + targetNode,
        status: 'success',
        buttonId: buttonId,
        nodeId: targetNode,
        sensorId: targetSensor,
        value: payloadToSend,
        // Este ramo e o BYPASS: REPRESENT, FORCE_UPDATE, DEBUG e intervalo saem
        // sem esperar ACK nenhum. Carimbar command/type real impede que o
        // Monitor os anuncie como "Atuacao Confirmada / ACK recebido".
        command: cmdToSend,
        type: typeToSend
    }];
}

var item = {
    mqttMsg: mqttMsg,
    targetNode: targetNode,
    targetSensor: targetSensor,
    buttonId: buttonId,
    payload: payloadToSend
};

if (context.get('waiting')) {
    var queue = context.get('queue') || [];
    queue.push(item);
    context.set('queue', queue);
    node.warn('ACK pendente — enfileirado. Fila: ' + queue.length);
    return [null, {
        payload: 'Ocupado: ACK pendente para Nó ' + context.get('targetNode') + '. Enfileirado (posição ' + queue.length + ')',
        status: 'pending',
        buttonId: buttonId
    }];
}

iniciarItem(item);
return null;

initialize:
context.set('waiting', false);
context.set('queue', []);
context.set('retries', 0);
context.set('timer', null);

func:
// Decodifica tópico nativo: {prefix}/out/{nodeId}/{sensorId}/{command}/{ack}/{type}
// ou formato JSON M360: msg.payload = {nodeId, sensorId, command, ack, type, payload}
var MQTT_PREFIX = global.get('mqtt_topic_prefix') || 'm360/DF/0000';
var parts = msg.topic.split('/');

// --- Formato nativo MySensors (9+ segmentos) ---
if (parts.length >= 9) {
    var nodeId   = parseInt(parts[4]);
    var sensorId = parseInt(parts[5]);
    var command  = parseInt(parts[6]);
    var ack      = parseInt(parts[7]);
    var type     = parseInt(parts[8]);
    if ([nodeId, sensorId, command, ack, type].some(isNaN)) {
        return null;
    }
    msg.payload = {
        nodeId:    nodeId,
        sensorId:  sensorId,
        command:   command,
        ack:       ack,
        type:      type,
        payload:   typeof msg.payload === 'string' ? msg.payload : String(msg.payload),
    // ack=1 nunca vem de um no neste sistema: e o ACK de transporte que o
    // gateway fabrica em publishTransportAck() assim que o radio confirma o
    // salto. Rotular como 'transport_ack' impede que seja confundido com
    // confirmacao do no -- ver o Sincronizador ACK.
        direction: ack === 1 ? 'transport_ack' : 'sensor',
        timestamp: Math.floor(Date.now() / 1000)
    };
    msg.topic = MQTT_PREFIX + '/out';
    return msg;
}

// --- Formato JSON M360 gateway (tópico plano, payload JSON) ---
var m = msg.payload;
if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch(e) { return null; }
}
if (!m || m.nodeId === undefined || m.command === undefined) {
    return null;
}
msg.payload = {
    nodeId:    m.nodeId,
    sensorId:  m.sensorId,
    command:   m.command,
    ack:       m.ack || 0,
    type:      m.type,
    payload:   String(m.payload !== undefined ? m.payload : ''),
    direction: (m.direction === 'ack' || m.ack == 1) ? 'transport_ack' : 'sensor',
    timestamp: Math.floor(Date.now() / 1000)
};
msg.topic = MQTT_PREFIX + '/out';
return msg;

// Registro de nos dirigido 100% pela apresentacao do proprio no (MySensors).
// Tipo e rotulo de cada child vem do payload de present(); nome/versao do no vem de I_SKETCH_NAME / I_SKETCH_VERSION.
// Toda re-apresentacao (command 0 ou payload "REPRESENT") limpa dados antigos e dispara atualizacao imediata do Dashboard.
var TTL_MS = flow.get('nodes_ttl_ms') || 172800000;
var m = msg.payload;
if (typeof m === 'string') { try { m = JSON.parse(m); } catch(e) { return null; } }
if (!m || !m.nodeId) return null;

var PRESENTATION = {
    0:'S_DOOR',1:'S_MOTION',2:'S_SMOKE',3:'S_BINARY',4:'S_DIMMER',5:'S_COVER',
    6:'S_TEMP',7:'S_HUM',8:'S_BARO',9:'S_WIND',10:'S_RAIN',11:'S_UV',12:'S_WEIGHT',
    13:'S_POWER',14:'S_HEATER',15:'S_DISTANCE',16:'S_LIGHT_LEVEL',17:'S_ARDUINO_NODE',
    18:'S_ARDUINO_REPEATER_NODE',19:'S_LOCK',20:'S_IR',21:'S_WATER',22:'S_AIR_QUALITY',
    23:'S_CUSTOM',24:'S_DUST',25:'S_SCENE_CONTROLLER',26:'S_RGB_LIGHT',27:'S_RGBW_LIGHT',
    28:'S_COLOR_SENSOR',29:'S_HVAC',30:'S_MULTIMETER',31:'S_SPRINKLER',32:'S_WATER_LEAK',
    33:'S_SOUND',34:'S_VIBRATION',35:'S_MOISTURE',36:'S_INFO',37:'S_GAS',38:'S_GPS',39:'S_WATER_QUALITY'
};

function deriveCategory(nodeObj) {
    if (nodeObj.nodeId === 0) return 'Gateway Central';
    var childs = nodeObj.childs || {};
    var types = Object.values(childs).map(function(c) { return c.tipo; });

    if (types.includes('S_MOISTURE')) return 'Monitoramento de Solo (Talhoes)';
    if (types.includes('S_TEMP') || types.includes('S_HUM') || types.includes('S_BARO') || types.includes('S_WIND') || types.includes('S_RAIN')) return 'Estacao Meteorologica / Clima';
    if (types.includes('S_BINARY') || types.includes('S_SPRINKLER') || types.includes('S_HEATER') || types.includes('S_COVER')) return 'Controle de Atuacao (Irrigacao/Bombas)';
    if (types.includes('S_WATER') || types.includes('S_WATER_LEAK') || types.includes('S_WATER_QUALITY')) return 'Reservatorio / Qualidade da Agua';

    return nodeObj.sketchName ? ('No: ' + nodeObj.sketchName) : 'Modulo IoT Geral';
}

var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var now = Date.now();

// Limpeza TTL de nos inativos
Object.keys(nodes).forEach(function(id) {
    if (now - nodes[id].lastSeen > TTL_MS) {
        node.warn('No ' + id + ' removido do mapa por TTL');
        delete nodes[id];
    }
});

// Descoberta / registro inicial de novo no
if (!nodes[m.nodeId]) {
    nodes[m.nodeId] = {
        nodeId: m.nodeId,
        discovered: now,
        lastSeen: now,
        lastHeartbeat: null,
        lastAck: null,
        status: 'NEW',
        messages: 0,
        values: {},
        childs: {},
        sketchName: '',
        sketchVersion: '',
        presentName: '',
        batteryLevel: null,
        batteryVoltage: null,
        intervalMin: null,
        timeoutSec: 450,
        categoria: 'Modulo IoT Geral'
    };
    node.warn('Novo no descoberto: ' + m.nodeId);
}

var n = nodes[m.nodeId];
if (!n.values) n.values = {};
if (!n.childs) n.childs = {};

// Cadencia observada entre ciclos de despertar
var prevSeen = n.lastSeen;
if (prevSeen) {
    var gap = now - prevSeen;
    if (gap > 15000) {
        n.cycleMs = n.cycleMs ? Math.round(0.7 * n.cycleMs + 0.3 * gap) : gap;
    }
}
n.lastSeen = now;
n.messages++;

var isRePresentation = false;

// Trata solicitacao explicita de reapresentacao do no ou Gateway
if (m.payload === 'REPRESENT' || (m.command === 1 && m.type === 48 && m.payload === 'REPRESENT')) {
    n.childs = {}; // Limpa filhos antigos para reconstrucao dinamica sem sensores fantasmas
    n.prunePending = true; // valores orfaos sao podados adiante, nao aqui
    isRePresentation = true;
    node.warn('Solicitacao de Reapresentacao recebida para o No ' + m.nodeId + '. Tabela de filhos resetada.');
}

// Apresentacao (command 0): captura tipo e rotulo enviados pelo no
if (m.command === 0) {
    isRePresentation = true;
    if (m.sensorId === 255) {
        // Apresentacao de No: S_ARDUINO_NODE (17) ou S_ARDUINO_REPEATER_NODE (18).
        // E a PRIMEIRA mensagem do boot, ~2 s antes das apresentacoes de child --
        // o unico ponto seguro para zerar a tabela. O comentario antigo aqui
        // prometia esse reset, mas o codigo nunca o fazia: por isso o No 99
        // acumulou 28 childs, os canonicos (11, 12, 21, 31-39) convivendo com a
        // numeracao de firmwares antigos (0-6, 16-23), e o No 2 ficou com um
        // child 0 duplicando o child 1.
        //
        // NAO ampliar para "qualquer sensorId 255 com command 0": o no tambem
        // envia type 30 (versao da lib) DEPOIS dos childs, e zerar ali apagaria
        // o que acabou de ser apresentado.
        if (m.type === 17 || m.type === 18) {
            n.childs = {};
            n.prunePending = true;
            node.warn('No ' + m.nodeId + ': apresentacao de no -- tabela de childs zerada para reconstrucao.');
        }
        if (m.payload && typeof m.payload === 'string' && m.payload.trim() !== '') {
            n.presentName = m.payload.trim();
        }
    } else {
        // Apresentacao de Sensor/Atuador (Child Presentation)
        var tipoStr = PRESENTATION[m.type] || 'S_CUSTOM';
        var alias = (m.payload && typeof m.payload === 'string' && m.payload.trim() !== '') ? m.payload.trim() : null;
        var existing = n.childs[m.sensorId] || {};
        n.childs[m.sensorId] = {
            childId: m.sensorId,
            tipo: tipoStr,
            de: alias || existing.de || ('Sensor ' + m.sensorId)
        };
        node.warn('No ' + m.nodeId + ': child apresentado (ID ' + m.sensorId + ' / ' + (alias || 'sem rotulo') + ' / ' + tipoStr + ')');
    }
}

// Leitura (command 1): armazena o valor transmitido
// m.ack == 1 e o ACK de transporte fabricado pelo gateway: carrega o valor que
// o gateway MANDOU, nao o que o no aplicou. Registra-lo em values[] mostrava no
// dashboard estado de rele que nunca foi confirmado por ninguem.
if (m.command === 1 && m.ack != 1) {
    n.values[m.sensorId] = m.payload;
    if (m.sensorId === 255) {
        n.batteryVoltage = parseFloat(m.payload);
    } else if (m.sensorId === 254) {
        var iv = parseInt(m.payload, 10);
        if (!isNaN(iv) && iv > 0) {
            n.intervalMin = iv;   // timeoutSec e calculado adiante, em ponto unico
        }
    } else if (!n.childs[m.sensorId]) {
        n.childs[m.sensorId] = {childId: m.sensorId, tipo: 'S_CUSTOM', de: 'Sensor ' + m.sensorId};
    }
}

// Timeout de inatividade, em ponto unico: o MAIOR entre a cadencia declarada
// pelo no (child 254) e a cadencia observada (cycleMs), mais Delta T =
// max(2 min, 50%).
//
// Por que o maior dos dois: M360Node so transmite um sensor quando o valor muda
// ou a cada 10 ciclos (staleForced = _nNoUpdates >= 10, M360Node.cpp). Um no
// ALWAYS_ON com intervalMin = 1 pode entao ficar ate ~11 min em silencio
// legitimo. Derivar o timeout so do intervalo declarado dava 180 s, e o No 99
// era marcado OFFLINE em toda janela sem mudanca de leitura -- node_lost falso,
// recorrente, e alerta de Telegram junto. Nos LOW_POWER nao tem esse problema
// (o smartSleep emite I_PRE/POST_SLEEP_NOTIFICATION a cada ciclo, tipos 32/33),
// e para eles os dois valores coincidem: o max() nao muda nada.
var baseSec = 0;
if (n.intervalMin) { baseSec = n.intervalMin * 60; }

// Piso deterministico para no sem sleep. O sufixo [ON] / [REP] no sketch name
// vem de M360Node::begin() e marca o perfil que roda por millis(), sem dormir:
// nele o pior caso de silencio legitimo e STALE_FORCE_CYCLES (10) intervalos,
// porque _readAndSendAll() so reenvia sensor sem variacao a cada 10 ciclos.
// Sem este piso o limiar so chegava la por convergencia da media movel, e cada
// passo custava um node_lost falso. No [LP] nao entra: o smartSleep emite
// I_PRE/POST_SLEEP_NOTIFICATION todo ciclo.
// Espelha NodeRegistry::recalcTimeout() -- contrato de dois lados, ver §9.
var semSleep = /\[(ON|REP)\]/.test(n.sketchName || '');
if (semSleep && baseSec > 0) { baseSec = baseSec * 10; }

if (n.cycleMs)     { baseSec = Math.max(baseSec, Math.round(n.cycleMs / 1000)); }
if (baseSec > 0) {
    n.timeoutSec = baseSec + Math.max(120, Math.round(baseSec * 0.5));
}

// Mensagens Internas (command 3): nome/versao de sketch, bateria e heartbeat
if (m.command === 3) {
    if (m.type === 0) {
        n.batteryLevel = parseInt(m.payload);
    } else if (m.type === 11) {
        n.sketchName = m.payload;
        isRePresentation = true;
        node.warn('No ' + m.nodeId + ': Re-apresentacao de Sketch -> ' + m.payload);
    } else if (m.type === 12) {
        n.sketchVersion = m.payload;
        isRePresentation = true;
    } else if (m.type === 22) {
        n.lastHeartbeat = now;
    }
}

if (m.ack == 1) { n.lastAck = now; }

// Poda de valores orfaos -- adiada de proposito para a primeira telemetria que
// chega DEPOIS da rajada de apresentacao, quando a tabela de childs ja esta
// completa.
//
// Zerar n.values junto com n.childs na apresentacao apagava o estado dos 9 reles
// do No 99, e ele nao volta sozinho: atuador nao responde C_REQ
// (M360Node::handleMessage() so atende kind == M360_SENSOR), entao o valor so
// reapareceria no proximo comando -- dashboard sem indicacao de solenoide ate a
// proxima rega. Podando aqui, o estado conhecido sobrevive a re-apresentacao e
// so sai o que o no deixou de declarar.
if (n.prunePending && m.command === 1 && Object.keys(n.childs).length > 0) {
    var RESERVADOS = {253: 1, 254: 1, 255: 1};
    Object.keys(n.values).forEach(function(cid) {
        if (!n.childs[cid] && !RESERVADOS[cid]) {
            delete n.values[cid];
            node.warn('No ' + m.nodeId + ': valor orfao do child ' + cid + ' removido (nao consta na apresentacao).');
        }
    });
    delete n.prunePending;
}

// Atualiza a categoria dinamicamente com base nas caracteristicas reais do no
n.categoria = deriveCategory(n);

try { global.set('mys_nodes', nodes, 'file'); } catch (e) { global.set('mys_nodes', nodes); }

if (isRePresentation) {
    node.warn('Re-apresentacao processada para No ' + m.nodeId + ' (' + (n.sketchName || 'No ' + m.nodeId) + ') - Atualizando Dashboard!');
}

return msg;

// Watchdog proativo - registra último contato do gateway
var now = Date.now();
var wasOnline = flow.get('gateway_online');
flow.set('gateway_last_seen', now);
flow.set('gateway_online', true);
node.status({fill:'green', shape:'dot', text:'Online: ' + new Date(now).toLocaleTimeString()});

if (wasOnline === false) {
    // Gateway estava offline e restabeleceu comunicação
    return {
        payload: {
            alerta: 'GATEWAY ONLINE',
            ultimoContato: new Date(now).toLocaleString('pt-BR')
        }
    };
}
return null;

// Alerta proativo se gateway ficar offline ou online
var GATEWAY_TIMEOUT_MS = 120000; // 2 minutos sem mensagem = alerta
var lastSeen = flow.get('gateway_last_seen');
var now = Date.now();
if (!lastSeen) {
    node.status({fill:'grey', shape:'ring', text:'Aguardando primeiro contato...'});
    return null;
}
var diff = now - lastSeen;
if (diff > GATEWAY_TIMEOUT_MS) {
    flow.set('gateway_online', false);
    node.status({fill:'red', shape:'ring', text:'OFFLINE há ' + Math.round(diff/1000) + 's'});
    msg.payload = {
        alerta: 'GATEWAY OFFLINE',
        ultimoContato: new Date(lastSeen).toLocaleString('pt-BR'),
        semRespostaHa: Math.round(diff/1000) + ' segundos'
    };
    return msg;
} else {
    var wasOnline = flow.get('gateway_online');
    node.status({fill:'green', shape:'dot', text:'OK - último contato há ' + Math.round(diff/1000) + 's'});
    if (wasOnline === false) {
        flow.set('gateway_online', true);
        msg.payload = {
            alerta: 'GATEWAY ONLINE',
            ultimoContato: new Date(lastSeen).toLocaleString('pt-BR')
        };
        return msg;
    }
    return null;
}

// Remove nos inativos por TTL e forca atualizacao reativa da UI e do Dropdown
var TTL_MS = flow.get('nodes_ttl_ms') || 172800000;
var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var now = Date.now();
var removidos = [];
Object.keys(nodes).forEach(function(id) {
    if (now - nodes[id].lastSeen > TTL_MS) {
        removidos.push(id);
        delete nodes[id];
    }
});
try { global.set('mys_nodes', nodes, 'file'); } catch (e) { global.set('mys_nodes', nodes); }
if (removidos.length > 0) {
    node.warn('TTL: Nos removidos por expiracao: ' + removidos.join(', '));
    msg.payload = {removidos: removidos, restantes: Object.keys(nodes).length};
    return msg;
}
return null;

// Mapa construido apenas a partir dos atributos apresentados pelo no.
// Sem relabel hardcoded por nodeId e sem dados de demonstracao.
var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var now = Date.now();
var prefix = global.get('mqtt_topic_prefix') || 'm360/DF/0000';
var UNIT = {S_TEMP:' \u00b0C', S_HUM:' %', S_LIGHT_LEVEL:' %', S_WATER:' L/min', S_DISTANCE:' cm'};
function fmtValor(tipo, v) {
    if (v === undefined || v === null) return '-';
    if (tipo === 'S_BINARY') return (v == '1' || String(v).toUpperCase() === 'LIGADO') ? 'LIGADO' : 'DESLIGADO';
    return String(v) + (UNIT[tipo] || '');
}
// O status do gateway era o literal 'ONLINE': o mapa mostrava o gateway no ar
// enquanto o 'Verifica Gateway Offline' (mesma aba, mesmo escopo de flow)
// disparava alerta de OFFLINE no Telegram. Agora le a mesma fonte.
var gwOnline = flow.get('gateway_online');
var redeMapa = {
    gateway: {
        id: '0 (Gateway Central)',
        topico_status: prefix + '/gateway/status',
        status: (gwOnline === false) ? 'OFFLINE' : ((gwOnline === true) ? 'ONLINE' : 'DESCONHECIDO')
    },
    nos: []
};
for (var id in nodes) {
    var n = nodes[id];
    var age = (now - n.lastSeen) / 1000;
    // MESMO criterio do 'Watchdog da rede' (aba MQTT): intervalo declarado pelo
    // no (child 254, gravado em timeoutSec por 'Mapeia nos') + delta T. Antes
    // aqui era 3 x cycleMs limitado a [300, 21600] e la era timeoutSec: o mesmo
    // no podia aparecer ONLINE no mapa e OFFLINE na tabela de watchdog.
    var offThr = n.timeoutSec ||
        (n.intervalMin
            ? (n.intervalMin * 60 + Math.max(120, n.intervalMin * 60 * 0.5))
            : (n.cycleMs
                ? Math.round(n.cycleMs / 1000 + Math.max(120, (n.cycleMs / 1000) * 0.5))
                : 450));
    var statusNode = 'ONLINE';
    if (age > offThr) statusNode = 'OFFLINE';
    else if (n.lastHeartbeat && (now - n.lastHeartbeat) / 1000 > 900) statusNode = 'SEM HEARTBEAT';
    var descricaoNode = n.sketchName ? (n.sketchName + (n.sketchVersion ? ' (v' + n.sketchVersion + ')' : ''))
                                     : (n.presentName || ('No ' + id));
    var noInfo = {nodeId:id, categoria:(n.categoria || 'No IoT'), status:statusNode, lastSeenStr:Math.round(age)+'s atras',
        descricao:descricaoNode, batteryLevel:n.batteryLevel, batteryVoltage:n.batteryVoltage, childs:[]};
    var values = n.values || {};
    var childs = n.childs || {};
    var sensorIds = Object.keys(childs).sort(function(a,b) { return Number(a) - Number(b); });
    var seenDe = {};
    sensorIds.forEach(function(childId) {
        var child = childs[childId];
        var deStr = String(child.de).trim();
        // Keep the latest childId for each 'de' (since it's sorted, later childIds overwrite older ones)
        seenDe[deStr] = {childId:childId, tipo:child.tipo, de:child.de, valor:fmtValor(child.tipo, values[childId])};
    });
    // Convert object values back to array
    Object.keys(seenDe).forEach(function(k) {
        noInfo.childs.push(seenDe[k]);
    });
    redeMapa.nos.push(noInfo);
}
msg.payload = redeMapa;
return msg;

// Rotear umidade do solo Canteiro A (Nó 01) dinamicamente para gráficos
var m = msg.payload;
if (!m || m.nodeId === undefined) return null;

// So leitura real de sensor. Estes filtros recebem a saida `direction ==
// 'sensor'` do switch, que inclui APRESENTACAO (command 0) e mensagens
// INTERNAS (command 3). Numa apresentacao o payload e o ROTULO do child --
// parseFloat("B_1m_10cm") = NaN -- e ia direto para o grafico e para o
// historico. Todo REPRESENT envenenava as series.
if (Number(m.command) !== 1 || Number(m.ack) === 1) { return null; }

var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var n = nodes[m.nodeId];
var child = n && n.childs && n.childs[m.sensorId];

var isNode01 = (Number(m.nodeId) === 1) || 
               (child && child.de && child.de.startsWith('A_')) || 
               (n && (n.sketchName === '01nodeSolo3dNano' || n.presentName === '01nodeSolo3dNano'));

// 37 = V_LEVEL, que e o que os Nos 1 e 2 enviam de fato (inventario.md secao 9);
// 3 = V_PERCENTAGE, caso o remap ocorra antes. O 35 do teste antigo e V_VOLUME
// na tabela V_*: era o numero de S_MOISTURE (tabela S_*) usado numa comparacao
// de tipo de variavel. `child.tipo === 'V_LEVEL'` era condicao morta -- `tipo`
// guarda sempre um S_*, nunca um V_*.
var isSoilMoisture = (Number(m.type) === 37 || Number(m.type) === 3 ||
                      (child && child.tipo === 'S_MOISTURE'));

if (isNode01 && isSoilMoisture) {
    var label = (child && child.de) ? child.de : (n ? (n.sketchName + ' S' + m.sensorId) : ('Nó 01 S' + m.sensorId));
    msg.topic = label;
    msg.payload = parseFloat(m.payload);
    msg.ts = Date.now();
    return msg;
}
return null;

// Rotear medições de Temperatura e Umidade do Ar do Nó 99 (NodeReles)
var m = msg.payload;
if (!m || m.nodeId === undefined || Number(m.nodeId) !== 99) return null;

// So leitura real de sensor. Estes filtros recebem a saida `direction ==
// 'sensor'` do switch, que inclui APRESENTACAO (command 0) e mensagens
// INTERNAS (command 3). Numa apresentacao o payload e o ROTULO do child --
// parseFloat("B_1m_10cm") = NaN -- e ia direto para o grafico e para o
// historico. Todo REPRESENT envenenava as series.
if (Number(m.command) !== 1 || Number(m.ack) === 1) { return null; }

var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var n = nodes[m.nodeId];
var child = n && n.childs && n.childs[m.sensorId];

// Com a guarda de command acima, type 0/1 sao V_TEMP/V_HUM. Sem ela, type 0
// em command 3 e I_BATTERY_LEVEL: o nivel de bateria do No 99 era plotado no
// grafico de temperatura. `child.tipo === 'V_TEMP'/'V_HUM'` era condicao morta.
var isTemp = (Number(m.type) === 0 || Number(m.sensorId) === 11 || (child && child.tipo === 'S_TEMP'));
var isHum  = (Number(m.type) === 1 || Number(m.sensorId) === 12 || (child && child.tipo === 'S_HUM'));

if (isTemp) {
    var labelTemp = (child && child.de) ? child.de : (n ? (n.sketchName || 'Nó 99') : 'Nó 99');
    msg.topic = 'Temperatura - ' + labelTemp;
    msg.payload = parseFloat(m.payload);
    msg.ts = Date.now();
    return msg;
} else if (isHum) {
    var labelHum = (child && child.de) ? child.de : (n ? (n.sketchName || 'Nó 99') : 'Nó 99');
    msg.topic = 'Umidade Ar - ' + labelHum;
    msg.payload = parseFloat(m.payload);
    msg.ts = Date.now();
    return msg;
}
return null;

var CUTOFF = 7 * 86400000; // 7 dias
var hist = flow.get('hist_solo_A') || [];
// ts ausente virava NaN no filtro abaixo e zerava o historico inteiro.
var _ts = (typeof msg.ts === 'number' && isFinite(msg.ts)) ? msg.ts : Date.now();
hist.push({ topic: msg.topic, payload: msg.payload, ts: _ts });
var now = Date.now();
hist = hist.filter(function(p) { return (now - p.ts) < CUTOFF; });
if (hist.length > 3000) { hist = hist.slice(-3000); }
flow.set('hist_solo_A', hist);
return msg;

var CUTOFF = 7 * 86400000; // 7 dias
var hist = flow.get('hist_clima') || [];
// ts ausente virava NaN no filtro abaixo e zerava o historico inteiro.
var _ts = (typeof msg.ts === 'number' && isFinite(msg.ts)) ? msg.ts : Date.now();
hist.push({ topic: msg.topic, payload: msg.payload, ts: _ts });
var now = Date.now();
hist = hist.filter(function(p) { return (now - p.ts) < CUTOFF; });
if (hist.length > 3000) { hist = hist.slice(-3000); }
flow.set('hist_clima', hist);
return msg;

// Rotear telemetria de clima e solo do Nó 04 (SolarMini) para gráficos
var m = msg.payload;
if (!m || m.nodeId === undefined || Number(m.nodeId) !== 4) return null;

// So leitura real de sensor. Estes filtros recebem a saida `direction ==
// 'sensor'` do switch, que inclui APRESENTACAO (command 0) e mensagens
// INTERNAS (command 3). Numa apresentacao o payload e o ROTULO do child --
// parseFloat("B_1m_10cm") = NaN -- e ia direto para o grafico e para o
// historico. Todo REPRESENT envenenava as series.
if (Number(m.command) !== 1 || Number(m.ack) === 1) { return null; }

var sensorId = Number(m.sensorId);
var val = parseFloat(m.payload);
if (isNaN(val)) return null;

var type = Number(m.type);
var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var n = nodes[m.nodeId];
var child = n && n.childs && n.childs[sensorId];

var isTempAr = (sensorId === 11);
var isHumAr = (sensorId === 12);
var isTempSolo = (sensorId === 1);

if (isTempAr) {
    msg.topic = 'Temperatura Ar';
    msg.payload = val;
    msg.ts = Date.now();
    return msg;
} else if (isHumAr) {
    msg.topic = 'Umidade do Ar';
    msg.payload = val;
    msg.ts = Date.now();
    return msg;
} else if (isTempSolo) {
    msg.topic = 'Temperatura Solo';
    msg.payload = val;
    msg.ts = Date.now();
    return msg;
}

return null;

var CUTOFF = 7 * 86400000; // 7 dias
var hist = flow.get('hist_solar') || [];
// ts ausente virava NaN no filtro abaixo e zerava o historico inteiro.
var _ts = (typeof msg.ts === 'number' && isFinite(msg.ts)) ? msg.ts : Date.now();
hist.push({ topic: msg.topic, payload: msg.payload, ts: _ts });
var now = Date.now();
hist = hist.filter(function(p) { return (now - p.ts) < CUTOFF; });
if (hist.length > 3000) { hist = hist.slice(-3000); }
flow.set('hist_solar', hist);
return msg;

// Rotear nivel de bateria (I_BATTERY_LEVEL / V_VOLTAGE) de QUALQUER no que se apresentar
var m = msg.payload;
if (!m || m.nodeId === undefined) return null;

// Este filtro trata os DOIS caminhos de bateria (command 3/I_BATTERY_LEVEL e
// command 1/V_VOLTAGE), entao nao restringe command -- so descarta o ACK de
// transporte fabricado pelo gateway, que carrega o valor comandado.
if (Number(m.ack) === 1) { return null; }

var isNativeBattery = (Number(m.command) === 3 && Number(m.type) === 0); // I_BATTERY_LEVEL (%)
var isVoltageChild = (Number(m.command) === 1 && (Number(m.sensorId) === 255 || Number(m.type) === 38)); // V_VOLTAGE (V)

if (isNativeBattery || isVoltageChild) {
    var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
    var n = nodes[m.nodeId];
    var nodeLabel = n ? (n.sketchName || n.presentName || ('No ' + m.nodeId)) : ('No ' + m.nodeId);

    if (isNativeBattery) {
        msg.topic = 'Nível Bateria (%) - ' + nodeLabel;
    } else {
        msg.topic = 'Tensão Bateria (V) - ' + nodeLabel;
    }
    msg.payload = parseFloat(m.payload);
    msg.ts = Date.now();
    return msg;
}
return null;

var CUTOFF = 7 * 86400000; // 7 dias
var hist = flow.get('hist_bateria') || [];
// ts ausente virava NaN no filtro abaixo e zerava o historico inteiro.
var _ts = (typeof msg.ts === 'number' && isFinite(msg.ts)) ? msg.ts : Date.now();
hist.push({ topic: msg.topic, payload: msg.payload, ts: _ts });
var now = Date.now();
hist = hist.filter(function(p) { return (now - p.ts) < CUTOFF; });
if (hist.length > 3000) { hist = hist.slice(-3000); }
flow.set('hist_bateria', hist);
return msg;

// Rotear vazao (S_WATER / V_FLOW) e acumular volume de QUALQUER no com hidrometro/sensor de vazao
var m = msg.payload;
if (!m || m.nodeId === undefined) return null;

// So leitura real de sensor. Estes filtros recebem a saida `direction ==
// 'sensor'` do switch, que inclui APRESENTACAO (command 0) e mensagens
// INTERNAS (command 3). Numa apresentacao o payload e o ROTULO do child --
// parseFloat("B_1m_10cm") = NaN -- e ia direto para o grafico e para o
// historico. Todo REPRESENT envenenava as series.
if (Number(m.command) !== 1 || Number(m.ack) === 1) { return null; }

var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var n = nodes[m.nodeId];
var child = n && n.childs && n.childs[m.sensorId];

var isFlowSensor = (Number(m.type) === 34 || (child && (child.tipo === 'S_WATER' || child.tipo === 'S_WATER_LEAK')));

if (isFlowSensor) {
    var flowRate = parseFloat(m.payload) || 0.0;
    var now = Date.now();
    var nodeKey = 'flow_vol_node_' + m.nodeId + '_' + m.sensorId;
    var lastTsKey = 'flow_ts_node_' + m.nodeId + '_' + m.sensorId;

    var lastTs = flow.get(lastTsKey);
    // Acumulador em escopo GLOBAL: o 'Radar M360' da aba IA Reporter lia esta
    // chave com flow.get() de OUTRA aba, onde ela nunca existiu -- o volume
    // saia sempre 0 no relatorio diario. Migra o valor de flow uma unica vez.
    var volume = global.get(nodeKey);
    if (volume === undefined || volume === null) { volume = flow.get(nodeKey) || 0.0; }

    if (lastTs && flowRate > 0) {
        var dt = (now - lastTs) / 1000; // segundos decorridos
        // Aceita intervalo de até 300s (5 min) entre leituras periódicas do nó
        if (dt > 0 && dt <= 300) {
            var dV = (flowRate / 60.0) * dt; // Vazão L/min * (dt/60) = Litros acumulados
            volume += dV;
            global.set(nodeKey, volume);
        }
    }
    flow.set(lastTsKey, now);

    var label = (child && child.de) ? child.de : (n ? (n.sketchName || ('Nó ' + m.nodeId)) : ('Nó ' + m.nodeId));
    // Padroniza label limpo sem duplicatas
    var cleanLabel = label.replace(/No /g, 'Nó ');

    var flowRateLps = flowRate / 60.0; // Converte L/min para Litros por segundo (L/s)
    var msgVazao = {
        topic: 'Vazão (L/s) - ' + cleanLabel,
        payload: parseFloat(flowRateLps.toFixed(3)),
        ts: now
    };
    // `ts` e OBRIGATORIO: 'Salvar Historico Volume' filtra por (now - p.ts) e
    // sem ts isso vira NaN < CUTOFF === false, descartando TODA entrada --
    // inclusive a recem-inserida. O historico de volume ficava eternamente
    // vazio enquanto o acumulador marcava centenas de litros.
    var msgVolume = {
        topic: 'Volume - ' + cleanLabel,
        payload: parseFloat(volume.toFixed(2)),
        ts: now
    };
    return [msgVazao, msgVolume];
}
return null;

var CUTOFF = 7 * 86400000; // 7 dias
var hist = flow.get('hist_vazao') || [];
// ts ausente virava NaN no filtro abaixo e zerava o historico inteiro.
var _ts = (typeof msg.ts === 'number' && isFinite(msg.ts)) ? msg.ts : Date.now();
hist.push({ topic: msg.topic, payload: msg.payload, ts: _ts });
var now = Date.now();
hist = hist.filter(function(p) { return (now - p.ts) < CUTOFF; });
if (hist.length > 3000) { hist = hist.slice(-3000); }
flow.set('hist_vazao', hist);
return msg;

var CUTOFF = 7 * 86400000; // 7 dias
var hist = flow.get('hist_volume') || [];
// ts ausente virava NaN no filtro abaixo e zerava o historico inteiro.
var _ts = (typeof msg.ts === 'number' && isFinite(msg.ts)) ? msg.ts : Date.now();
hist.push({ topic: msg.topic, payload: msg.payload, ts: _ts });
var now = Date.now();
hist = hist.filter(function(p) { return (now - p.ts) < CUTOFF; });
if (hist.length > 3000) { hist = hist.slice(-3000); }
flow.set('hist_volume', hist);
return msg;

// Rotear umidade do solo Canteiro B (Nó 02) dinamicamente para gráficos
var m = msg.payload;
if (!m || m.nodeId === undefined) return null;

// So leitura real de sensor. Estes filtros recebem a saida `direction ==
// 'sensor'` do switch, que inclui APRESENTACAO (command 0) e mensagens
// INTERNAS (command 3). Numa apresentacao o payload e o ROTULO do child --
// parseFloat("B_1m_10cm") = NaN -- e ia direto para o grafico e para o
// historico. Todo REPRESENT envenenava as series.
if (Number(m.command) !== 1 || Number(m.ack) === 1) { return null; }

var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var n = nodes[m.nodeId];
var child = n && n.childs && n.childs[m.sensorId];

var isNode02 = (Number(m.nodeId) === 2) || 
               (child && child.de && (child.de.startsWith('M_') || child.de.startsWith('B_'))) || 
               (n && (n.sketchName === '02nodeSolo3dNano' || n.presentName === '02nodeSolo3dNano'));

// 37 = V_LEVEL, que e o que os Nos 1 e 2 enviam de fato (inventario.md secao 9);
// 3 = V_PERCENTAGE, caso o remap ocorra antes. O 35 do teste antigo e V_VOLUME
// na tabela V_*: era o numero de S_MOISTURE (tabela S_*) usado numa comparacao
// de tipo de variavel. `child.tipo === 'V_LEVEL'` era condicao morta -- `tipo`
// guarda sempre um S_*, nunca um V_*.
var isSoilMoisture = (Number(m.type) === 37 || Number(m.type) === 3 ||
                      (child && child.tipo === 'S_MOISTURE'));

if (isNode02 && isSoilMoisture) {
    var label = (child && child.de) ? child.de : (n ? (n.sketchName + ' S' + m.sensorId) : ('Nó 02 S' + m.sensorId));
    msg.topic = label;
    msg.payload = parseFloat(m.payload);
    msg.ts = Date.now();
    return msg;
}
return null;

var CUTOFF = 7 * 86400000; // 7 dias
var hist = flow.get('hist_solo_B') || [];
// ts ausente virava NaN no filtro abaixo e zerava o historico inteiro.
var _ts = (typeof msg.ts === 'number' && isFinite(msg.ts)) ? msg.ts : Date.now();
hist.push({ topic: msg.topic, payload: msg.payload, ts: _ts });
var now = Date.now();
hist = hist.filter(function(p) { return (now - p.ts) < CUTOFF; });
if (hist.length > 3000) { hist = hist.slice(-3000); }
flow.set('hist_solo_B', hist);
return msg;

var hist = flow.get('hist_solo_B') || [];
var msgs = hist.map(function(p) { return { topic: p.topic, payload: p.payload, ts: p.ts }; });
node.status({ fill: 'blue', shape: 'dot', text: 'replay B: ' + msgs.length + ' pontos' });
return [ msgs.length ? msgs : null ];

// Logger centralizado com amostragem/debounce de atualizacao para proteger o Dashboard
var logs = global.get('mqtt_logs') || [];
var dir = msg.mqtt_dir || 'IN';
var topic = msg.topic || 'N/A';
var payload = msg.payload;

var payloadStr = '';
if (typeof payload === 'object') {
    try { payloadStr = JSON.stringify(payload); } catch(e) { payloadStr = String(payload); }
} else {
    payloadStr = String(payload);
}

var entry = {
    timestamp: new Date().toISOString(),
    dir: dir,
    topic: topic,
    payload: payloadStr
};

logs.push(entry);
if (logs.length > 6000) {
    logs.shift();
}
global.set('mqtt_logs', logs);

// Throttle UI table updates (maximo 1 atualizacao a cada 800ms para evitar travamentos)
var lastUiUpdate = flow.get('mqtt_log_last_ui') || 0;
var now = Date.now();
if (now - lastUiUpdate < 800) {
    return null; // Acumula no log sem re-renderizar a tabela na UI
}
flow.set('mqtt_log_last_ui', now);

var recent = logs.slice(-100).reverse();
msg.payload = recent.map(function(item) {
    var d = new Date(item.timestamp);
    var pad = function(n) { return n < 10 ? '0' + n : n; };
    var timeStr = pad(d.getHours()) + ':' + pad(d.getMinutes()) + ':' + pad(d.getSeconds());
    var dateStr = pad(d.getDate()) + '/' + pad(d.getMonth() + 1) + '/' + d.getFullYear() + ' ' + timeStr;
    return {
        DataHora: dateStr,
        Direcao: item.dir,
        Topico: item.topic,
        Payload: item.payload
    };
});
return msg;

global.set('mqtt_logs', []);
msg.payload = [];
return msg;

var logs = global.get('mqtt_logs') || [];
var lines = [];
lines.push('"Timestamp","Direction","Topic","Payload"');

for (var i = 0; i < logs.length; i++) {
    var item = logs[i];
    var ts = item.timestamp || '';
    var dir = item.dir || '';
    var topic = (item.topic || '').replace(/"/g, '""');
    var payload = (item.payload || '').replace(/"/g, '""');
    lines.push('"' + ts + '","' + dir + '","' + topic + '","' + payload + '"');
}

var csvStr = lines.join('\n');
msg.headers = {
    'Content-Type': 'text/csv; charset=utf-8',
    'Content-Disposition': 'attachment; filename="mqtt_log_m360_' + Date.now() + '.csv"'
};
msg.payload = csvStr;
return msg;

// Monitor Inteligente de Conectividade, Comandos, Caixa Postal e Alertas Telegram
var botToken = env.get("TELEGRAM_BOT_TOKEN") || global.get("TELEGRAM_BOT_TOKEN") || "";
var chatId = env.get("TELEGRAM_CHAT_ID") || global.get("TELEGRAM_CHAT_ID") || "";

var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch(e) { nodes = global.get('mys_nodes') || {}; }
var now = Date.now();

var nodeStates = flow.get('node_connection_states') || {};
var lastAlertTimes = flow.get('last_network_alert_times') || {};
var lastParamValues = flow.get('last_param_values') || {};

function getNodeDesc(id) {
    var n = nodes[id];
    if (!n) return "Nó " + id;
    return (n.sketchName || n.presentName || ("Nó " + id)) + (n.sketchVersion ? " v" + n.sketchVersion : "");
}

function getChildDesc(nId, cId) {
    var n = nodes[nId];
    if (n && n.childs && n.childs[cId]) {
        return n.childs[cId].de || ("Child " + cId);
    }
    if (cId === 254) return "Intervalo de Transmissão";
    if (cId === 255) return "Bateria";
    if (cId === 253) return "Debug";
    return "Child " + cId;
}

var agoraStr = new Date().toLocaleTimeString("pt-BR", {hour: "2-digit", minute: "2-digit", second: "2-digit"});
var dataStr = new Date().toLocaleDateString("pt-BR");

var text = "";
var alertKey = "";
var COOLDOWN_LOST_MS = 5 * 60 * 1000;
var COOLDOWN_RECON_MS = 2 * 60 * 1000;

// ─── 1. Eventos do Gateway (m360/+/+/out/events) ─────────────────
if (msg.topic && msg.topic.includes('/events')) {
    var ev = msg.payload;
    if (typeof ev === 'string') { try { ev = JSON.parse(ev); } catch(e) {} }
    if (!ev || ev.nodeId === undefined) return null;

    var nId = String(ev.nodeId);
    var currentState = nodeStates[nId] || 'ONLINE';
    var nodeData = nodes[nId] || {};

    // Perda de nó (node_lost)
    if (ev.event === 'node_lost') {
        var lastLostAlert = lastAlertTimes['lost_' + nId] || 0;
        if (currentState !== 'OFFLINE' && (now - lastLostAlert > COOLDOWN_LOST_MS)) {
            nodeStates[nId] = 'OFFLINE';
            lastAlertTimes['lost_' + nId] = now;

            var motivoStr = "";
            // O motivo cita o timeoutSec que 'Mapeia nos' realmente aplicou
            // (max entre intervalo declarado e cadencia observada). Recalcular
            // aqui so a partir de intervalMin produzia texto contraditorio:
            // "> 620 s (Intervalo: 1 min + ΔT: 2 min)".
            if (nodeData.timeoutSec) {
                var partes = [];
                if (nodeData.intervalMin) { partes.push("intervalo declarado " + nodeData.intervalMin + " min"); }
                if (nodeData.cycleMs) { partes.push("cadencia observada " + (Math.round(nodeData.cycleMs / 6000) / 10) + " min"); }
                motivoStr = "Inatividade detectada: > " + nodeData.timeoutSec + " s" +
                            (partes.length ? " (" + partes.join(" / ") + ")" : "");
            } else if (ev.details) {
                motivoStr = ev.details;
            } else {
                motivoStr = "Inatividade detectada (> " + (nodeData.timeoutSec || 450) + " s sem transmissão)";
            }

            text = "⚠️ *ALERTA DE CONECTIVIDADE: Nó Inativo*\n\n" +
                   "📍 *Dispositivo:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
                   "⏱️ *Motivo:* " + motivoStr + "\n" +
                   "📶 *Wi-Fi do gateway:* " + (ev.rssi ? ev.rssi + " dBm" : "N/A") + "\n" +
                   "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")\n\n" +
                   "⚙️ _O gateway avisará assim que o nó restabelecer contato._";
        } else {
            nodeStates[nId] = 'OFFLINE';
            return null;
        }
    }

    // Reconexão (node_reconnected)
    else if (ev.event === 'node_reconnected') {
        var lastReconAlert = lastAlertTimes['recon_' + nId] || 0;
        if ((currentState === 'OFFLINE' || lastAlertTimes['lost_' + nId]) && (now - lastReconAlert > COOLDOWN_RECON_MS)) {
            nodeStates[nId] = 'ONLINE';
            lastAlertTimes['recon_' + nId] = now;
            delete lastAlertTimes['lost_' + nId];

            text = "✅ *COMUNICAÇÃO RESTABELECIDA: Nó Online*\n\n" +
                   "📍 *Dispositivo:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
                   "📶 *Wi-Fi do gateway:* " + (ev.rssi ? ev.rssi + " dBm" : "N/A") + "\n" +
                   "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")";
        } else {
            nodeStates[nId] = 'ONLINE';
            return null;
        }
    }

    // Apresentação de Novo Nó / Sketch
    else if (ev.event === 'node_sketch_name') {
        alertKey = 'sketch_' + nId;
        if (now - (lastAlertTimes[alertKey] || 0) > 30000) {
            lastAlertTimes[alertKey] = now;
            text = "📋 *NÓ IDENTIFICADO NA REDE*\n\n" +
                   "📍 *Dispositivo:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
                   "🏷️ *Detalhes:* " + (ev.details || "Apresentação de sketch recebida") + "\n" +
                   "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")";
        }
    }
}

// ─── 2. Telemetria e Respostas do Nó (Decodificador MySensors) ───
else if (msg.payload && msg.payload.nodeId !== undefined && msg.payload.command !== undefined) {
    var m = msg.payload;
    var nId = String(m.nodeId);

    // Resposta / Confirmação de Intervalo (Child 254 / V_VAR1)
    if (m.sensorId === 254 && m.command === 1 && m.ack !== 1) {
        var newInterval = parseInt(m.payload, 10);
        var lastVal = lastParamValues['interval_' + nId];

        if (newInterval > 0 && newInterval !== lastVal) {
            lastParamValues['interval_' + nId] = newInterval;
            flow.set('last_param_values', lastParamValues);

            text = "⏱️ *PARÂMETRO CONFIRMADO: Intervalo de Envio*\n\n" +
                   "📍 *Dispositivo:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
                   "⚙️ *Novo Intervalo:* *" + newInterval + " min*\n" +
                   "📡 *Status:* Aplicado com sucesso na EEPROM do nó\n" +
                   "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")";
        }
    }
}

// ─── 3. Respostas de Comandos, Fila e Caixa Postal (Mailbox) ─────
else if (msg.status && msg.nodeId !== undefined) {
    var nId = String(msg.nodeId);
    var cId = Number(msg.sensorId);

    // Comando retido na Caixa Postal (Nó em Sono)
    if (msg.status === 'mailbox_enqueued') {
        text = "⏳ *COMANDO ENFILEIRADO: Nó em Hibernação*\n\n" +
               "📍 *Destino:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
               "⚙️ *Comando:* " + (msg.desc || ("Ajustar Child " + cId + " = " + msg.value)) + "\n" +
               "💤 *Status:* Nó em modo Low Power. Salvo na Caixa Postal para entrega automática no próximo despertar.\n" +
               "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")";
    }

    // Comando despachado da Caixa Postal (Nó acabou de acordar)
    else if (msg.status === 'mailbox_dispatched') {
        text = "🎯 *NÓ DESPERTOU: Comando Despachado*\n\n" +
               "📍 *Destino:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
               "⚙️ *Comando:* " + (msg.desc || ("Child " + cId + " = " + msg.value)) + "\n" +
               "📡 *Status:* Despachado ao Gateway durante a janela ativa de despertar\n" +
               "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")";
    }

    // Sucesso de comando imediato (Always-On ou já acordado)
    else if (msg.status === 'success') {
        // Atuacao de verdade e C_SET (1) + V_STATUS (2). Sem este teste, o
        // sensorId 0 do painel administrativo caia em `cId < 200` e o
        // REPRESENT era anunciado como "Atuador Child 0 -- DESLIGADO (0) --
        // ACK recebido com sucesso": falso nos tres pontos, porque nao e
        // atuacao, o valor era a string "REPRESENT" e esse comando sai por
        // bypass, sem ACK nenhum.
        var isAtuacao = (Number(msg.command) === 1 && Number(msg.type) === 2);

        alertKey = 'cmd_ok_' + nId + '_' + cId;
        if (now - (lastAlertTimes[alertKey] || 0) > 3000) {
            lastAlertTimes[alertKey] = now;

            if (cId === 254) {
                text = "🎯 *COMANDO ENVIADO: Ajustar Intervalo*\n\n" +
                       "📍 *Destino:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
                       "⏱️ *Intervalo Solicitado:* " + msg.value + " min\n" +
                       "📡 *Status:* Despachado ao Gateway / Nó\n" +
                       "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")";
            } else if (!isAtuacao) {
                text = "📤 *COMANDO ADMINISTRATIVO DESPACHADO*\n\n" +
                       "📍 *Destino:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
                       "⚙️ *Comando:* " + String(msg.value) + "\n" +
                       "📡 *Status:* Entregue ao gateway — este comando não aguarda ACK\n" +
                       "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")\n\n" +
                       "_A confirmação real, quando houver, chega como telemetria do nó._";
            } else if (cId > 0 && cId < 200) {
                var estadoStr = (String(msg.value) === '1') ? "LIGADO (1)" : "DESLIGADO (0)";
                text = "🎯 *COMANDO EXECUTADO: Atuação Confirmada*\n\n" +
                       "📍 *Dispositivo:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
                       "🔌 *Atuador:* " + getChildDesc(nId, cId) + " (Child " + cId + ")\n" +
                       "⚡ *Estado:* *" + estadoStr + "*\n" +
                       "✅ *Confirmação:* ACK recebido com sucesso\n" +
                       "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")";
            }
        }
    }

    // Falha / Timeout de ACK
    else if (msg.status === 'error') {
        alertKey = 'ack_fail_' + nId + '_' + cId;
        if (now - (lastAlertTimes[alertKey] || 0) > 60000) {
            lastAlertTimes[alertKey] = now;
            text = "🚨 *FALHA DE COMANDO: Timeout de ACK*\n\n" +
                   "📍 *Alvo:* " + getNodeDesc(nId) + " (ID: " + nId + ")\n" +
                   "🔌 *Atuador / Child:* " + getChildDesc(nId, cId) + " (ID " + cId + ")\n" +
                   "⚠️ *Detalhe:* O nó não confirmou a execução após 3 tentativas consecutivas.\n" +
                   "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")";
        }
    }
}

// ─── 4. Watchdogs de Gateway ─────────────────────────────────────
else if (msg.payload && msg.payload.alerta === 'GATEWAY OFFLINE') {
    alertKey = 'gateway_offline';
    if (now - (lastAlertTimes[alertKey] || 0) > 5 * 60 * 1000) {
        lastAlertTimes[alertKey] = now;
        text = "🚨 *ALERTA CRÍTICO: Gateway Central Offline*\n\n" +
               "📍 *Gateway:* Gateway Central M360 (ESP8266)\n" +
               "⏱️ *Sem resposta há:* " + (msg.payload.semRespostaHa || "mais de 2 minutos") + "\n" +
               "🕒 *Último Contato:* " + (msg.payload.ultimoContato || agoraStr) + "\n\n" +
               "⚠️ _Verifique a alimentação do gateway ou o enlace WiFi da estufa._";
    }
}
else if (msg.payload && (msg.payload.alerta === 'GATEWAY ONLINE' || msg.payload.alerta === 'GATEWAY RECONNECTED')) {
    alertKey = 'gateway_offline';
    delete lastAlertTimes[alertKey];
    text = "✅ *COMUNICAÇÃO RESTABELECIDA: Gateway Central Online*\n\n" +
           "📍 *Gateway:* Gateway Central M360 (ESP8266)\n" +
           "⏱️ *Status:* Enlace restabelecido e operando normalmente\n" +
           "🕒 *Horário:* " + agoraStr + " (" + dataStr + ")";
}

flow.set('node_connection_states', nodeStates);
flow.set('last_network_alert_times', lastAlertTimes);

if (!text) return null;

msg.payload = {
    chat_id: chatId,
    text: text,
    parse_mode: "Markdown"
};
msg.url = "https://api.telegram.org/bot" + botToken + "/sendMessage";
node.status({fill: "green", shape: "dot", text: "Alerta enviado: " + agoraStr});
return msg;

// Chaves de Configuração
var GEMINI_API_KEY = global.get('GEMINI_API_KEY') || 'COLE_AQUI';
var TELEGRAM_BOT_TOKEN = env.get('TELEGRAM_BOT_TOKEN') || global.get('TELEGRAM_BOT_TOKEN') || '';
var TELEGRAM_CHAT_ID = env.get('TELEGRAM_CHAT_ID') || global.get('TELEGRAM_CHAT_ID') || '';

// 1. Puxa os logs MQTT das últimas 24 horas (armazenados em RAM pelo Central Logger)
var logsArray = global.get('mqtt_logs') || [];
var now = Date.now();
var MS_24H = 24 * 60 * 60 * 1000;

// Filtra estritamente as últimas 24h
var logs24h = logsArray.filter(function(item) {
    if (!item.timestamp) return true;
    var ts = new Date(item.timestamp).getTime();
    return (now - ts) <= MS_24H;
});

// 2. Extração e Agregação de Métricas das Últimas 24h (D-0)
var metrics24h = {
    totalLogs: logs24h.length,
    irrigCount: 0,
    flowVolumeL: 0,
    tempMin: 999,
    tempMax: -999,
    tempSum: 0,
    tempCount: 0,
    humSum: 0,
    humCount: 0,
    nodeLostEvents: 0,
    nodeReconEvents: 0,
    commandsSent: 0,
    commandsConfirmed: 0
};

var logsText = "";
logs24h.forEach(function(item) {
    var pStr = typeof item.payload === 'object' ? JSON.stringify(item.payload) : String(item.payload);
    logsText += item.timestamp + ' | ' + item.dir + ' | ' + item.topic + ' | ' + pStr + '\n';

    // Contabiliza eventos
    if (item.topic && item.topic.includes('/events')) {
        if (pStr.includes('node_lost')) metrics24h.nodeLostEvents++;
        if (pStr.includes('node_reconnected')) metrics24h.nodeReconEvents++;
    }
    if (item.dir === 'OUT' || (item.topic && item.topic.includes('/in/'))) {
        metrics24h.commandsSent++;
    }
    if (item.dir === 'IN' && item.topic && item.topic.includes('/out/99/')) {
        if (item.topic.endsWith('/2/0/2') || item.topic.endsWith('/1/0/2')) {
            metrics24h.commandsConfirmed++;
            if (pStr === '1' || pStr === 'true') metrics24h.irrigCount++;
        }
    }
    // Clima DHT11 (Child 11 / Child 12 ou 40 / 41)
    if (item.topic && (item.topic.includes('/99/11/') || item.topic.includes('/99/40/'))) {
        var t = parseFloat(item.payload);
        if (!isNaN(t) && t > -50 && t < 100) {
            if (t < metrics24h.tempMin) metrics24h.tempMin = t;
            if (t > metrics24h.tempMax) metrics24h.tempMax = t;
            metrics24h.tempSum += t;
            metrics24h.tempCount++;
        }
    }
    if (item.topic && (item.topic.includes('/99/12/') || item.topic.includes('/99/41/'))) {
        var h = parseFloat(item.payload);
        if (!isNaN(h) && h >= 0 && h <= 100) {
            metrics24h.humSum += h;
            metrics24h.humCount++;
        }
    }
});

// Puxa o volume acumulado dos fluxos atuais
// Escopo GLOBAL: estas chaves sao escritas pelo 'Filtro Vazao e Volume' na
// aba ACK Handling. Lidas com flow.get() daqui davam sempre undefined -> 0.
var volA = global.get('flow_vol_node_99_21') || global.get('flow_vol_node_99_34') || 0;
metrics24h.flowVolumeL = parseFloat(volA) || 0;
metrics24h.tempAvg = metrics24h.tempCount > 0 ? parseFloat((metrics24h.tempSum / metrics24h.tempCount).toFixed(1)) : null;
metrics24h.humAvg = metrics24h.humCount > 0 ? parseFloat((metrics24h.humSum / metrics24h.humCount).toFixed(0)) : null;
if (metrics24h.tempMin === 999) metrics24h.tempMin = null;
if (metrics24h.tempMax === -999) metrics24h.tempMax = null;

// 3. Recupera Métricas do Dia Anterior (D-1) salvas no contexto global
var prevDay = global.get('m360_daily_metrics_prev') || null;

var d1Text = "MÉTRICAS DO DIA ANTERIOR (D-1):\n";
if (prevDay) {
    d1Text += JSON.stringify(prevDay, null, 2);
} else {
    d1Text += "Primeiro ciclo de execução - sem histórico prévio consolidado de D-1 registrado.";
}

var currentDaySummary = "MÉTRICAS CONSOLIDADAS DAS ÚLTIMAS 24H (D-0):\n" + JSON.stringify(metrics24h, null, 2);

// 4. Monta o Prompt com a Persona Radar M360 (m360-agent-log-analyst)
var system_prompt = "Você é o Radar M360, o agente sênior especialista em telemetria IoT, diagnóstico de rede MySensors/MQTT, auditoria agroclimática e engenharia de soluções da estufa inteligente (Projeto M360 Horta).\n\n" +
"MISSÃO: Gerar a AUDITORIA DIÁRIA CONSOLIDADA DAS ÚLTIMAS 24 HORAS (fechamento às 08:00 AM) com COMPARATIVO OBRIGATÓRIO EM RELAÇÃO AO DIA ANTERIOR (D-1).\n\n" +
"ESTRUTURA DO RELATÓRIO (Markdown elegante para Telegram):\n\n" +
"🛰️ *RADAR M360 — AUDITORIA DIÁRIA & TELEMETRIA 24H*\n" +
"📅 *Período:* Últimas 24 horas (Fechamento: 08:00 AM)\n\n" +
"📊 *1. PAINEL COMPARATIVO 24H (Hoje vs Ontem D-1)*\n" +
"Apresente tópicos comparando as métricas de Hoje com Ontem com a variação percentual (Δ %):\n" +
"• 💧 *Volume de Irrigação:* {Hoje} L vs {Ontem} L (Δ {delta}%)\n" +
"• ⚡ *Ciclos de Atuação / Irrigação:* {Hoje} vs {Ontem}\n" +
"• 🌡️ *Microclima Médio:* {Temp Méd} °C (Mín: {Min}°C / Máx: {Max}°C) | Umid: {Umid Méd}%\n" +
"• 📡 *Estabilidade de Rede:* {Quedas Hoje} eventos de node_lost vs {Quedas Ontem}\n\n" +
"🩺 *2. DIAGNÓSTICO DE REDE & PROTOCOLO MYSENSORS*\n" +
"• Avaliação de nós: Nó 01 (Solo A), Nó 02 (Solo B), Nó 04 (SolarMini), Nó 99 (Atuadores/Clima/Vazão).\n" +
"• Análise de entregas, ACKs e estabilidade do enlace RF24/Gateway.\n\n" +
"🌱 *3. CORRELAÇÃO HIDRÁULICA & AGRONÔMICA*\n" +
"• Correlação entre comandos de válvulas e fluxo medido pelo sensor YF-S201.\n" +
"• Comportamento da umidade do solo nos canteiros.\n\n" +
"⭐ *4. ÍNDICE DE SAÚDE OPERACIONAL: {Nota}/10*\n" +
"Justificativa sucinta da pontuação com base nos dados.\n\n" +
"💡 *5. RECOMENDAÇÕES TÉCNICAS E AGRONÔMICAS PARA HOJE*\n" +
"Orientações preventivas claras para o operador da estufa.\n\n";

if (logsText.length > 70000) {
    logsText = logsText.substring(logsText.length - 70000);
}

msg.gemini_key = GEMINI_API_KEY;
msg.telegram_token = TELEGRAM_BOT_TOKEN;
msg.telegram_chat_id = TELEGRAM_CHAT_ID;
msg.currentMetrics = metrics24h;

msg.payload = {
    "contents": [{
        "parts": [{
            "text": system_prompt + "\n\n" + d1Text + "\n\n" + currentDaySummary + "\n\n--- LOGS MQTT BRUTOS (AMOSTRA 24H) ---\n" + logsText
        }]
    }],
    "systemInstruction": {
        "parts": [{
            "text": "Escreva sempre em Português do Brasil de forma técnica, fluida, analítica e com emojis adequados para o Telegram. Use formatação Markdown compatível."
        }]
    }
};

msg.headers = { "Content-Type": "application/json" };
return msg;

if (!msg.payload || !msg.payload.candidates || msg.payload.candidates.length === 0) {
    node.error("Detalhes do erro do Gemini: " + JSON.stringify(msg.payload), msg);
    return null;
}

var text = msg.payload.candidates[0].content.parts[0].text;

// Salva as métricas de hoje para servirem como base D-1 no dia seguinte
if (msg.currentMetrics) {
    msg.currentMetrics.date = new Date().toISOString().split('T')[0];
    global.set('m360_daily_metrics_prev', msg.currentMetrics);
}

// Dispara para todos os inscritos e chat principal
var subscribers = global.get("telegram_subscribers") || [];
if (!Array.isArray(subscribers)) subscribers = [subscribers];

var chatIds = [];
var mainChat = msg.telegram_chat_id || env.get("TELEGRAM_CHAT_ID") || global.get("TELEGRAM_CHAT_ID") || "";
chatIds.push(String(mainChat));

subscribers.forEach(function(s) {
    var id = s && (s.chatId || s);
    if (id && chatIds.indexOf(String(id)) === -1) {
        chatIds.push(String(id));
    }
});

var msgs = [];
chatIds.forEach(function(cId) {
    msgs.push({
        payload: {
            chat_id: cId,
            text: text,
            parse_mode: "Markdown"
        },
        url: "https://api.telegram.org/bot" + msg.telegram_token + "/sendMessage"
    });
});

return [msgs];

let nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
let now = Date.now();
let result = [];

for (const id in nodes) {
    let n = nodes[id];
    let age = (now - n.lastSeen) / 1000;
    let hb = n.lastHeartbeat ? (now - n.lastHeartbeat) / 1000 : 999999;
    let ack = n.lastAck ? (now - n.lastAck) / 1000 : 999999;

    // Timeout individual dinamico: Intervalo + Delta T
    let offThr = n.timeoutSec || (n.intervalMin ? (n.intervalMin * 60 + Math.max(120, (n.intervalMin * 60) * 0.5)) : (n.cycleMs ? Math.round(n.cycleMs / 1000 + Math.max(120, (n.cycleMs / 1000) * 0.5)) : 450));

    let status = "ONLINE";
    if (age > offThr) {
        status = "OFFLINE";
    } else if (hb > 900) {
        status = "SEM HEARTBEAT";
    } else if (ack > 1800) {
        status = "SEM ACK";
    }
    n.status = status;

    let lastSeenStr = Math.round(age) + "s atrás";
    let heartbeatStr = n.lastHeartbeat ? Math.round(hb) + "s atrás" : "-";
    let ackStr = n.lastAck ? Math.round(ack) + "s atrás" : "-";

    result.push({
        nodeId: id,
        status: status,
        lastSeen: lastSeenStr,
        heartbeat: heartbeatStr,
        ack: ackStr
    });
}

msg.payload = result;
return msg;

var prefix = global.get('mqtt_topic_prefix') || 'm360/DF/0000';
var m = msg.payload;
if (typeof m === 'string') {
    try { m = JSON.parse(m); } catch(e) {}
}
if (m && typeof m === 'object' && m.nodeId !== undefined) {
    var nodeId   = m.nodeId;
    var sensorId = m.sensorId !== undefined ? m.sensorId : 0;
    var command  = m.command !== undefined ? m.command : 1;
    var ack      = m.ack !== undefined ? m.ack : 0;
    var type     = m.type !== undefined ? m.type : 2;
    var payload  = m.payload !== undefined ? String(m.payload) : '';
    msg.topic = prefix + '/in/' + nodeId + '/' + sensorId + '/' + command + '/' + ack + '/' + type;
    msg.payload = payload;
} else {
    msg.topic = prefix + '/in';
}
return msg;

var m = msg.payload;
var nodeId = m.nodeId || 1;
var action = m.action || "REPRESENT";

var payloadObj = {};
if (action === "REPRESENT") {
    payloadObj = {
        nodeId: Number(nodeId),
        sensorId: 0,
        command: 1,
        type: 48,
        payload: "REPRESENT"
    };
} else if (action === "FORCE_UPDATE") {
    payloadObj = {
        nodeId: Number(nodeId),
        sensorId: 0,
        command: 1,
        type: 48,
        payload: "FORCE_UPDATE"
    };
} else if (action === "DEBUG") {
    payloadObj = {
        nodeId: Number(nodeId),
        sensorId: 0,
        command: 1,
        type: 48,
        payload: "DEBUG_NET"
    };
}
msg.payload = payloadObj;
return msg;

// Regra A.1: Irrigacao Fixa do Canteiro A (Controle Tradicional - 6x1m, 35 alfaces)
// Sem considerar leitura de sensores.
//
// O comando NAO e publicado direto no broker. Sai como envelope para o
// Sincronizador ACK (link out), que monta o topico a partir de
// global.mqtt_topic_prefix, confirma pelo eco de aplicacao do no e REENVIA ate
// 3x se o no nao confirmar. Antes daqui saia topico literal 'm360/DF/0000/...'
// sem retentativa nenhuma: um OFF perdido no radio deixava a valvula aberta.
var NODE_RELES = 99;
var CHILD_SOL_A = 31;

var duracao = (msg.payload && msg.payload.duracao_segundos) ? msg.payload.duracao_segundos : 300;

function comando(child, valor) {
    return { payload: { nodeId: NODE_RELES, sensorId: child, command: 1, type: 2, payload: String(valor) } };
}

// Prazo de desligamento registrado FORA do function node. O setTimeout abaixo
// morre em qualquer redeploy; o 'Reconciliador de Irrigacao' (tick de 30 s) le
// este registro e fecha a valvula mesmo que este no tenha sido recarregado no
// meio da rega. O contexto global sobrevive a deploy (nao a restart do processo
// -- contra restart quem protege e o failsafe do firmware do No 99).
var MODO_A = 'Timer Fixo (Manejo Tradicional)';
var deadlines = global.get('m360_irrig_deadlines') || {};
deadlines[String(CHILD_SOL_A)] = {
    child: CHILD_SOL_A,
    canteiro: 'A',
    until: Date.now() + duracao * 1000,
    startedAt: Date.now(),
    duracao: duracao,
    modo: MODO_A
};
global.set('m360_irrig_deadlines', deadlines);

var msgTelegramStart = {
    telegram_event: {
        canteiro: "A",
        status: "INICIADA",
        duracao: duracao,
        modo: MODO_A,
        detalhes: "Parcela 6x1m | 35 pes de alface"
    }
};

var msgTelegramEnd = {
    telegram_event: {
        canteiro: "A",
        status: "FINALIZADA",
        duracao: duracao,
        modo: MODO_A
    }
};

node.status({fill: "green", shape: "dot", text: "Irrigando A por " + duracao + "s (Timer Fixo)"});

setTimeout(function () {
    // Se o Reconciliador ja fechou (prazo vencido durante um redeploy), o
    // registro nao existe mais e este timer nao deve mandar um OFF duplicado.
    var dl = global.get('m360_irrig_deadlines') || {};
    if (!dl[String(CHILD_SOL_A)]) { return; }
    delete dl[String(CHILD_SOL_A)];
    global.set('m360_irrig_deadlines', dl);
    node.send([comando(CHILD_SOL_A, 0), msgTelegramEnd]);
    node.status({fill: "grey", shape: "ring", text: "Canteiro A Standby"});
}, duracao * 1000);

return [comando(CHILD_SOL_A, 1), msgTelegramStart];

// Coleta leituras do No 2 (Solo B) e No 99 (Clima DHT11).
//
// Consome o objeto JA DECODIFICADO pelo 'Decodificador Nativo MySensors' (aba
// ACK Handling) via link in. Antes esta aba tinha o proprio `mqtt in` com
// prefixo literal e o proprio parser, que so entendia o topico nativo
// (parts.length >= 9): em modo JSON o coletor ficava mudo, soloB nunca enchia,
// o Motor de Regras respondia 'Sem leituras validas' e o Canteiro B NUNCA
// irrigava -- sem erro, sem log, sem alerta.
var m = msg.payload;
if (!m || typeof m !== 'object' || m.nodeId === undefined) { return null; }

// So leitura real de sensor: descarta apresentacao (command 0), interna
// (command 3) e o ACK de transporte fabricado pelo gateway (ack 1).
if (Number(m.command) !== 1 || Number(m.ack) === 1) { return null; }

var nodeId  = Number(m.nodeId);
var childId = Number(m.sensorId);
var subType = Number(m.type);
var val     = parseFloat(m.payload);
if (isNaN(val)) { return null; }

// 37 = V_LEVEL, que e o que os Nos 1 e 2 enviam de fato para solo (ver
// inventario.md secao 9); 3 = V_PERCENTAGE, caso o remap ocorra antes.
// O teste antigo usava 35, que na tabela V_* e V_VOLUME -- era o numero de
// S_MOISTURE (tabela S_*) usado numa comparacao de tipo de variavel.
if (nodeId === 2 && (subType === 37 || subType === 3)) {
    var soloB = flow.get('solo_b_readings') || {};
    soloB[childId] = { val: val, ts: Date.now() };
    flow.set('solo_b_readings', soloB);
}

if (nodeId === 99) {
    var clima = flow.get('clima_dht11') || { temp: 20.0, hum: 20.0 };
    if (childId === 11 && subType === 0) { clima.temp = val; }
    if (childId === 12 && subType === 1) { clima.hum = val; }
    flow.set('clima_dht11', clima);
}

return null;

// =========================================================================
// Motor Agroclimático Manejo360 — Canteiro B (Alface 6x1m)
// Integração: Solo 3D (Nó 2) + Clima DHT11 (Nó 99) + Agro-Meteorologia (Open-Meteo)
// =========================================================================
var soloB = flow.get("solo_b_readings") || {};
var clima = flow.get("clima_dht11") || { temp: 20.0, hum: 20.0 };
var agro = flow.get("agro_meteo") || flow.get("previsao_tempo") || {};
var now = Date.now();
var horaLocal = new Date().getHours();

// --- CAMADA 1: Trava de Absorção e Infiltração (Soak Time) ---
var lastIrrig = flow.get("last_irrig_b_time") || 0;
var soakTimeMin = (clima.temp < 18.0) ? 20 : 15;
var soakTimeMs = soakTimeMin * 60 * 1000;

if ((now - lastIrrig) < soakTimeMs) {
    var restMin = Math.ceil((soakTimeMs - (now - lastIrrig)) / 60000);
    node.status({fill: "yellow", shape: "ring", text: "Soak Time ativo (" + restMin + " min restantes)"});
    return null;
}

// --- CAMADA 2: Sanitização de Dados e Filtro de Outliers (Nó 2) ---
var validVals = [];
for (var childId in soloB) {
    var v = soloB[childId].val;
    if ((now - soloB[childId].ts) < 1800000) { // leituras dos últimos 30 min
        if (v >= 0 && v <= 1023) {
            validVals.push(v);
        }
    }
}

if (validVals.length === 0) {
    node.status({fill: "red", shape: "dot", text: "Sem leituras válidas no Solo B"});
    return null;
}

// Mediana sanitizada do solo
validVals.sort(function(a, b){ return a - b; });
var mid = Math.floor(validVals.length / 2);
var mediana = (validVals.length % 2 !== 0) ? validVals[mid] : (validVals[mid - 1] + validVals[mid]) / 2.0;

// --- CAMADA 3: Travas de Segurança Agroclimática e Janela Solar ---

// 3.1 Faixa de Capacidade de Campo (Solo Úmido)
if (mediana < 350) {
    node.status({fill: "green", shape: "dot", text: "Solo Úmido (Mediana: " + mediana.toFixed(1) + " ADC) - Standby"});
    return null;
}

// 3.2 Previsão de Chuva Iminente (> 70%) vs Estresse Hídrico Crítico (>= 700 ADC)
var LIMIAR_ESTRESSE_CRITICO = 700.0;
var probChuva = agro.probChuvaMax || 0;
var flagEmergenciaChuva = false;

if (probChuva > 70) {
    if (mediana < LIMIAR_ESTRESSE_CRITICO) {
        node.status({
            fill: "blue",
            shape: "ring",
            text: "🌧️ Adiada: Chuva prevista " + probChuva + "% (>70%) | Solo: " + mediana.toFixed(1) + " ADC (<" + LIMIAR_ESTRESSE_CRITICO + ")"
        });
        return null;
    } else {
        flagEmergenciaChuva = true;
    }
}

// 3.3 Trava de Pico de Radiação Solar (> 700 W/m² ou entre 12h e 13h)
// Evita choque térmico radicular e perda evaporativa extrema, exceto se solo muito seco (>= 650 ADC)
var radSolar = agro.radAtual || 0;
if ((radSolar > 700 || (horaLocal >= 12 && horaLocal <= 13)) && mediana < 650 && !flagEmergenciaChuva) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "☀️ Adiada: Pico de Radiação Solar (" + radSolar + " W/m²) | Solo: " + mediana.toFixed(1) + " ADC (<650)"
    });
    return null;
}

// 3.4 Trava de Risco Fúngico Noturno (Ponto de Orvalho ao anoitecer/madrugada)
var dewPoint = agro.pontoOrvalho || 15.0;
var tempLocal = clima.temp || agro.tempExt || 20.0;
var isNoite = (horaLocal >= 20 || horaLocal <= 5);
if (isNoite && (tempLocal - dewPoint < 1.5) && mediana < 650 && !flagEmergenciaChuva) {
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "🌿 Bloqueio Anti-Fúngico Noturno (T-Orvalho: " + (tempLocal - dewPoint).toFixed(1) + "°C) | Standby"
    });
    return null;
}

// --- CAMADA 4: Balanço Hídrico & Demanda Atmosférica (FAO-56 + VPD + Vento) ---
var vpd = agro.vpdAtual || 1.2; // kPa
var vento = agro.ventoAtual || 10.0; // km/h

// Fator multiplicador de demanda atmosférica
var F_atmo = 1.0;
if (vpd > 1.8) F_atmo += 0.15; // Estresse estomático / ar ressecado
if (vento > 20.0) F_atmo += 0.10; // Perda advectiva por vento
if (clima.temp > 25.0 && clima.hum < 18.0) F_atmo += 0.15; // Microclima interno extremo

// Lâmina d'água requerida (mm) com base no déficit do solo e demanda atmosférica
// Escala de reposição: 350 ADC (0 mm) a 850 ADC (3.5 mm de lâmina de reposição líquida)
var laminaMm = ((mediana - 350) / 500) * 3.5 * F_atmo;
if (laminaMm > 4.5) laminaMm = 4.5; // Teto de segurança (4.5 mm)

// Conversão para Volume (Litros) em canteiro de 6x1m (6 m²): 1 mm = 1 L/m² -> 6L por mm
var volumeLitros = laminaMm * 6.0;

// Tempo de acionamento em segundos (Vazão média nominal da linha de gotejamento = 2.5 L/min = 0.0416 L/s)
var VAZAO_L_POR_SEG = 2.5 / 60.0; // ~0.04167 L/s
var duracaoSegundos = Math.round(volumeLitros / VAZAO_L_POR_SEG);
if (duracaoSegundos > 600) duracaoSegundos = 600; // Cap de segurança em 10 minutos

// --- CAMADA 5: Regra de Corte Mínimo (> 3 minutos / 180s) ---
var MIN_TEMPO_SEG = 180; // 3 minutos
if (duracaoSegundos <= MIN_TEMPO_SEG) {
    var durMinStr = (duracaoSegundos / 60).toFixed(1);
    node.status({
        fill: "yellow",
        shape: "ring",
        text: "Standby: Lâmina " + laminaMm.toFixed(1) + "mm (" + durMinStr + " min / " + duracaoSegundos + "s) <= 3 min"
    });
    return null;
}

// --- COMANDOS & DISPARO ---
// Envelope para o Sincronizador ACK (link out), nao topico literal no broker:
// o topico vem de global.mqtt_topic_prefix e o OFF ganha 3 retentativas.
flow.set("last_irrig_b_time", now);

var NODE_RELES = 99;
var CHILD_SOL_B = 32;

function comando(child, valor) {
    return { payload: { nodeId: NODE_RELES, sensorId: child, command: 1, type: 2, payload: String(valor) } };
}

var msgOn  = comando(CHILD_SOL_B, 1);
var msgOff = comando(CHILD_SOL_B, 0);

var min = Math.floor(duracaoSegundos / 60);
var seg = duracaoSegundos % 60;
var duracaoFormatada = min + " min" + (seg > 0 ? " " + seg + "s" : "");

var modoStr = flagEmergenciaChuva
    ? "Emergência (Estresse Hídrico Crítico - Chuva " + probChuva + "% tardia)"
    : "Balanço Hídrico Agroclimático (FAO-56 Penman-Monteith)";

var detalhesAgro = "Mediana Solo: " + mediana.toFixed(1) + " ADC" +
    " | Lâmina: " + laminaMm.toFixed(1) + " mm (" + volumeLitros.toFixed(1) + " L)" +
    " | ET₀: " + (agro.et0Atual !== undefined ? agro.et0Atual : "-") + " mm/h" +
    " | VPD: " + (agro.vpdAtual !== undefined ? agro.vpdAtual : "-") + " kPa" +
    " | Radiação: " + (agro.radAtual !== undefined ? agro.radAtual : "-") + " W/m²" +
    " | Vento: " + (agro.ventoAtual !== undefined ? agro.ventoAtual : "-") + " km/h" +
    " | Chuva 4h: " + probChuva + "%" +
    " | Clima Estufa: " + clima.temp + "°C / " + clima.hum + "%";

var msgTelegramStart = {
    telegram_event: {
        canteiro: "B",
        status: "INICIADA",
        duracao: duracaoSegundos,
        modo: modoStr,
        detalhes: detalhesAgro + " | Tempo Projetado: " + duracaoFormatada
    }
};

var msgTelegramEnd = {
    telegram_event: {
        canteiro: "B",
        status: "FINALIZADA",
        duracao: duracaoSegundos,
        modo: modoStr
    }
};

node.status({
    fill: "blue",
    shape: "dot",
    text: "Irrigando B: " + laminaMm.toFixed(1) + "mm (" + duracaoFormatada + ") - Mediana: " + mediana.toFixed(1) + " ADC"
});

// Prazo registrado fora do function node: o setTimeout abaixo morre em
// qualquer redeploy, e ai quem fecha a valvula e o 'Reconciliador de Irrigacao'.
var deadlines = global.get('m360_irrig_deadlines') || {};
deadlines[String(CHILD_SOL_B)] = {
    child: CHILD_SOL_B,
    canteiro: 'B',
    until: now + duracaoSegundos * 1000,
    startedAt: now,
    duracao: duracaoSegundos,
    modo: modoStr
};
global.set('m360_irrig_deadlines', deadlines);

setTimeout(function() {
    var dl = global.get('m360_irrig_deadlines') || {};
    if (!dl[String(CHILD_SOL_B)]) { return; } // ja fechado pelo Reconciliador
    delete dl[String(CHILD_SOL_B)];
    global.set('m360_irrig_deadlines', dl);
    node.send([msgOff, msgTelegramEnd]);
    node.status({fill: "grey", shape: "ring", text: "Canteiro B Standby"});
}, duracaoSegundos * 1000);

return [msgOn, msgTelegramStart];

// Formatar e enviar notificação de início/fim de irrigação no Telegram
var botToken = env.get("TELEGRAM_BOT_TOKEN") || global.get("TELEGRAM_BOT_TOKEN") || "";
var chatId = env.get("TELEGRAM_CHAT_ID") || global.get("TELEGRAM_CHAT_ID") || "";

var event = msg.telegram_event || {};
if (!event.status) return null;

var emoji = (event.status === "INICIADA") ? "💧"
          : (event.status === "RECONCILIADA") ? "🚨" : "✅";
var canteiroNome = (event.canteiro === "B" || event.canteiro === "M") ? "Canteiro B (Manejo360)" : "Canteiro A (Controle Tradicional)";

var duracaoTexto = "";
if (event.duracao >= 60) {
    var min = Math.floor(event.duracao / 60);
    var seg = event.duracao % 60;
    duracaoTexto = min + " minuto" + (min > 1 ? "s" : "") + (seg > 0 ? " e " + seg + " segundo" + (seg > 1 ? "s" : "") : "");
} else {
    duracaoTexto = event.duracao + " segundos";
}

var texto = emoji + " *IRRIGAÇÃO " + event.status + "*\n\n" +
    "📍 *Local:* " + canteiroNome + "\n" +
    "⏱️ *Duração:* " + duracaoTexto + "\n" +
    "⚙️ *Modo:* " + event.modo + "\n";

if (event.detalhes) {
    texto += "📊 *Parâmetros Agroclimáticos:*\n • " + event.detalhes.split(" | ").join("\n • ") + "\n";
}

var agora = new Date().toLocaleTimeString("pt-BR", {hour: "2-digit", minute: "2-digit", second: "2-digit"});
texto += "\n🕒 *Horário:* " + agora + " (Horário de Brasília)";

msg.payload = {
    "chat_id": (chatId && chatId !== "COLE_AQUI") ? chatId : "@M360HortaBot",
    "text": texto,
    "parse_mode": "Markdown"
};

// Sem token nao ha para onde mandar. O fallback antigo montava
// ".../bot/sendMessage" e disparava um request garantidamente 404 a cada
// evento de irrigacao, escondendo a causa real (credencial ausente).
if (!botToken || botToken === "COLE_AQUI") {
    node.warn("TELEGRAM_BOT_TOKEN ausente — notificacao de irrigacao nao enviada.");
    node.status({fill: "red", shape: "ring", text: "Sem TELEGRAM_BOT_TOKEN"});
    return null;
}
msg.url = "https://api.telegram.org/bot" + botToken + "/sendMessage";

node.status({fill: "green", shape: "dot", text: "Telegram " + event.canteiro + " " + event.status});
return msg;

// Processa todas as variáveis agro-meteorológicas da Open-Meteo (-15.963944, -47.804028)
var data = msg.payload;
if (!data || !data.hourly || !data.hourly.time) {
    node.status({fill: "red", shape: "ring", text: "Erro: Resposta inválida da API"});
    return null;
}

var times = data.hourly.time;
var probs = data.hourly.precipitation_probability || [];
var precips = data.hourly.precipitation || [];
var temps = data.hourly.temperature_2m || [];
var hums = data.hourly.relative_humidity_2m || [];
var dews = data.hourly.dew_point_2m || [];
var et0s = data.hourly.et0_fao_evapotranspiration || [];
var vpds = data.hourly.vapour_pressure_deficit || [];
var rads = data.hourly.shortwave_radiation_instant || [];
var winds = data.hourly.wind_speed_10m || [];
var soilTemps = data.hourly.soil_temperature_0cm || [];
var soilMoists = data.hourly.soil_moisture_0_to_1cm || [];

var now = new Date();
var currentHourTs = now.getTime();

// 1. Identificar índice da hora corrente
var idxAtual = 0;
var menorDiff = Infinity;
for (var i = 0; i < times.length; i++) {
    var t = new Date(times[i]).getTime();
    var diff = Math.abs(t - currentHourTs);
    if (diff < menorDiff) {
        menorDiff = diff;
        idxAtual = i;
    }
}

// 2. Extrair dados instantâneos / hora atual
var et0Atual = et0s[idxAtual] || 0;
var vpdAtual = vpds[idxAtual] || 0;
var radAtual = rads[idxAtual] || 0;
var ventoAtual = winds[idxAtual] || 0;
var dewAtual = dews[idxAtual] || 0;
var tempAtual = temps[idxAtual] || 0;
var humAtual = hums[idxAtual] || 0;
var soilTempAtual = soilTemps[idxAtual] || 0;
var soilMoistAtual = soilMoists[idxAtual] || 0;

// 3. Analisar janela futura de 4 horas para chuva e ET0 acumulada do dia
var JANELA_HORAS = 4;
var probChuvaMax = 0;
var precipTotal4h = 0;
var et0AcumuladaDia = 0;
var horasDetalhadas = [];

var todayStr = now.toISOString().split("T")[0];

for (var j = 0; j < times.length; j++) {
    var tStr = times[j];
    if (tStr.startsWith(todayStr)) {
        et0AcumuladaDia += (et0s[j] || 0);
    }

    if (j >= idxAtual && j < idxAtual + JANELA_HORAS) {
        var p = probs[j] || 0;
        var prec = precips[j] || 0;
        if (p > probChuvaMax) probChuvaMax = p;
        precipTotal4h += prec;
        var hStr = tStr.split("T")[1] || tStr;
        horasDetalhadas.push(hStr + ": " + p + "% (" + prec.toFixed(1) + "mm)");
    }
}

var agroObj = {
    probChuvaMax: probChuvaMax,
    precipTotal4h: parseFloat(precipTotal4h.toFixed(1)),
    et0Atual: parseFloat(et0Atual.toFixed(2)),
    et0AcumuladaDia: parseFloat(et0AcumuladaDia.toFixed(2)),
    vpdAtual: parseFloat(vpdAtual.toFixed(2)),
    radAtual: parseFloat(radAtual.toFixed(0)),
    ventoAtual: parseFloat(ventoAtual.toFixed(1)),
    pontoOrvalho: parseFloat(dewAtual.toFixed(1)),
    tempExt: parseFloat(tempAtual.toFixed(1)),
    humExt: parseFloat(humAtual.toFixed(0)),
    soilTempModelo: parseFloat(soilTempAtual.toFixed(1)),
    soilMoistModelo: parseFloat(soilMoistAtual.toFixed(3)),
    janelaHoras: JANELA_HORAS,
    detalhesChuva: horasDetalhadas.join(" | "),
    updatedAt: Date.now(),
    updatedAtStr: new Date().toLocaleTimeString("pt-BR", {hour: "2-digit", minute: "2-digit"})
};

flow.set("agro_meteo", agroObj);
flow.set("previsao_tempo", agroObj);

var color = (probChuvaMax >= 70) ? "blue" : ((vpdAtual > 1.8) ? "yellow" : "green");
node.status({
    fill: color,
    shape: "dot",
    text: "ET₀: " + agroObj.et0Atual + "mm/h | VPD: " + agroObj.vpdAtual + "kPa | Rad: " + agroObj.radAtual + "W/m² | Chuva 4h: " + probChuvaMax + "%"
});

msg.payload = agroObj;
return msg;

// Reconciliador de Irrigacao -- rede de seguranca do desligamento.
//
// POR QUE EXISTE: o OFF da irrigacao era agendado por setTimeout() dentro do
// function node que ligou a valvula. Qualquer redeploy do Node-RED destroi esse
// timer e a valvula fica aberta indefinidamente. Este no roda a cada 30 s e nao
// depende de nenhum timer em memoria do no de origem.
//
// DUAS CAMADAS:
//  1. Prazo vencido -- fecha o child cujo `until` ja passou. O registro vive em
//     global.m360_irrig_deadlines, que sobrevive a deploy.
//  2. Backstop de valvula orfa -- solenoide que o registro do no mostra LIGADO
//     por mais tempo que o teto do firmware, sem prazo dono. O limiar e
//     DELIBERADAMENTE maior que o failsafe de 600 s de 99nodeReles.cpp: com o
//     firmware gravado, o no desliga primeiro e este ramo nunca dispara. Ele so
//     age quando o failsafe do no nao esta presente ou nao funcionou.
//
// LIMITE CONHECIDO: o contextStorage deste servidor e {default: 'memory'} --
// nao ha store 'file'. Um restart do PROCESSO apaga tanto os prazos quanto
// mys_nodes, e ai a unica protecao e o failsafe do firmware. Configurar um
// store 'file' em settings.js fecharia essa lacuna (tambem para mys_nodes).
//
// As bombas NFT (38/39) sao deliberadamente ignoradas: operam em regime
// continuo por projeto, exatamente como maxOnSecondsFor() do firmware define.
var NODE_RELES = 99;
var SOLENOIDES = [31, 32, 33];
var BACKSTOP_MS = 660000; // 11 min > 600 s do failsafe do No 99
var now = Date.now();

var cmds = [];
var avisos = [];

// --- 1. Prazos vencidos -------------------------------------------------
var deadlines = global.get('m360_irrig_deadlines') || {};
Object.keys(deadlines).forEach(function (k) {
    var d = deadlines[k];
    if (!d || typeof d.until !== 'number') { delete deadlines[k]; return; }
    if (now < d.until) { return; }

    delete deadlines[k];
    cmds.push({ payload: { nodeId: NODE_RELES, sensorId: d.child, command: 1, type: 2, payload: '0' } });
    avisos.push({ telegram_event: {
        canteiro: d.canteiro || '?',
        status: 'FINALIZADA',
        duracao: d.duracao || Math.round((now - (d.startedAt || now)) / 1000),
        modo: (d.modo || 'Irrigacao') + ' -- fechada pelo Reconciliador'
    }});
    node.warn('Reconciliador: prazo vencido do child ' + d.child + ' -- enviando OFF');
});
global.set('m360_irrig_deadlines', deadlines);

// --- 2. Backstop de valvula orfa ----------------------------------------
var nodes; try { nodes = global.get('mys_nodes', 'file') || {}; } catch (e) { nodes = global.get('mys_nodes') || {}; }
var n99 = nodes[NODE_RELES];
var since = context.get('valve_since') || {};

SOLENOIDES.forEach(function (child) {
    var ligado = !!(n99 && n99.values && String(n99.values[child]) === '1');
    if (!ligado) { delete since[child]; return; }

    // Tem prazo dono: a camada 1 cuida dele, o backstop nao interfere.
    if (deadlines[String(child)]) { since[child] = now; return; }

    if (!since[child]) { since[child] = now; return; }

    var abertoHaMs = now - since[child];
    if (abertoHaMs < BACKSTOP_MS) { return; }

    since[child] = now; // rearma, para nao repetir o OFF a cada 30 s
    cmds.push({ payload: { nodeId: NODE_RELES, sensorId: child, command: 1, type: 2, payload: '0' } });
    avisos.push({ telegram_event: {
        canteiro: '?',
        status: 'RECONCILIADA',
        duracao: Math.round(abertoHaMs / 1000),
        modo: 'Backstop: solenoide ' + child + ' ligado sem prazo ha mais de ' +
              Math.round(BACKSTOP_MS / 60000) + ' min -- failsafe do firmware nao atuou'
    }});
    node.error('Reconciliador: valvula orfa no child ' + child + ' -- forcando OFF');
});
context.set('valve_since', since);

// --- Status -------------------------------------------------------------
var pendentes = Object.keys(deadlines).length;
if (cmds.length > 0) {
    node.status({ fill: 'red', shape: 'dot', text: cmds.length + ' OFF forcado(s) | prazos: ' + pendentes });
} else if (pendentes > 0) {
    node.status({ fill: 'blue', shape: 'dot', text: 'Vigiando ' + pendentes + ' prazo(s) de rega' });
} else {
    node.status({ fill: 'grey', shape: 'ring', text: 'Sem rega em curso' });
}

return [cmds.length ? cmds : null, avisos.length ? avisos : null];
